import os
import time
import json
import random
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Set

import requests
from tqdm.auto import tqdm

# ---------- Helpers ----------
def ensure_values():
    missing = []
    if not USERNAME or USERNAME.strip().lower() in {"paste_twitter_username_here", "username"}:
        missing.append("USERNAME")
    if not AUTH_TOKEN or "PASTE_YOUR_auth_token" in AUTH_TOKEN:
        missing.append("AUTH_TOKEN")
    if not CT0 or "PASTE_YOUR_ct0" in CT0:
        missing.append("CT0")
    if not WEB_BEARER or "PASTE_CURRENT_WEB_BEARER_TOKEN_HERE" in WEB_BEARER:
        missing.append("WEB_BEARER")
    if missing:
        raise ValueError(f"Please paste valid values for: {', '.join(missing)}")

def build_session(auth_token: str, ct0: str, bearer: str) -> requests.Session:
    s = requests.Session()
    # Minimal, stable headers used by the web app
    s.headers.update({
        "Authorization": f"Bearer {bearer}",
        "x-csrf-token": ct0,
        "x-twitter-active-user": "yes",
        "x-twitter-client-language": "en",
        "accept": "*/*",
        "accept-language": "en-US,en;q=0.9",
        "referer": "https://twitter.com/",
        # A realistic desktop UA reduces the chance of anti-bot friction
        "user-agent": (
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
            "(KHTML, like Gecko) Chrome/123.0.0.0 Safari/537.36"
        ),
    })
    # Set cookies (domain .twitter.com so they apply to API subdomains)
    s.cookies.set("auth_token", auth_token, domain=".twitter.com")
    s.cookies.set("ct0", ct0, domain=".twitter.com")
    return s

def jitter_sleep(a: float, b: float):
    time.sleep(random.uniform(a, b))

def make_output_dir(base: str, username: str) -> str:
    out = os.path.join(base, username)
    Path(out).mkdir(parents=True, exist_ok=True)
    return out

def orig_image_url(url: str) -> str:
    # Ensure original size. pbs media often supports ?name=orig.
    if "?name=" in url:
        parts = url.split("?")
        qs = parts[1].split("&")
        qs = [kv for kv in qs if not kv.startswith("name=")]
        qs.append("name=orig")
        return parts[0] + "?" + "&".join(qs)
    elif "?" in url:
        return url + "&name=orig"
    else:
        return url + "?name=orig"

def parse_photo_urls_from_search_adaptive(resp: Dict) -> List[Tuple[str, str]]:
    """
    Extract (tweet_id, photo_url) from search/adaptive response.
    Only photo media (ignores videos/GIFs).
    """
    results = []
    tweets = resp.get("globalObjects", {}).get("tweets", {}) or {}
    for tid, tw in tweets.items():
        ext = tw.get("extended_entities", {}) or {}
        media_list = ext.get("media", []) or []
        for m in media_list:
            if m.get("type") == "photo":
                u = m.get("media_url_https") or m.get("media_url")
                if u:
                    results.append((tid, orig_image_url(u)))
    return results

def extract_next_cursor(resp: Dict) -> Optional[str]:
    """
    Extract the 'Bottom' cursor from search/adaptive timeline instructions.
    """
    timeline = resp.get("timeline", {}) or {}
    instructions = timeline.get("instructions", []) or []
    for instr in instructions:
        if "addEntries" in instr:
            entries = instr["addEntries"].get("entries", []) or []
            c = _find_bottom_cursor_in_entries(entries)
            if c:
                return c
        if "replaceEntry" in instr:
            entry = instr["replaceEntry"].get("entry", {}) or {}
            entries = [entry] if entry else []
            c = _find_bottom_cursor_in_entries(entries)
            if c:
                return c
    return None

def _find_bottom_cursor_in_entries(entries: List[Dict]) -> Optional[str]:
    for e in entries:
        content = e.get("content") or {}
        if content.get("entryType") == "TimelineTimelineCursor" or content.get("cursorType"):
            # two possible shapes
            # shape A: content = {"entryType":..., "value":..., "cursorType":"Bottom"}
            if content.get("cursorType") == "Bottom" and content.get("value"):
                return content.get("value")
            # shape B: content = {"operation": {"cursor": {"cursorType":"Bottom","value":"..."}}}
            op = content.get("operation") or {}
            cur = op.get("cursor") or {}
            if cur.get("cursorType") == "Bottom" and cur.get("value"):
                return cur.get("value")
        # sometimes nested under itemContent
        item = content.get("itemContent") or {}
        cur = item.get("value") if isinstance(item, dict) else None
        ctype = item.get("cursorType") if isinstance(item, dict) else None
        if ctype == "Bottom" and cur:
            return cur
    return None

def timeline_request(session: requests.Session, username: str, cursor: Optional[str]) -> Dict:
    # Internal web endpoint used by the legacy web client
    url = "https://api.twitter.com/2/search/adaptive.json"
    # Query filters: from:username filter:images exclude:retweets to favor original uploads
    q = f"from:{username} filter:images"
    params = {
        "q": q,
        "tweet_search_mode": "live",
        "count": 100,
        "include_ext_is_blue_verified": 1,
        "include_ext_verified_type": 1,
        "tweet_mode": "extended",
    }
    if cursor:
        params["cursor"] = cursor

    last_err = None
    for attempt in range(1, REQUEST_RETRIES + 1):
        try:
            r = session.get(url, params=params, timeout=30)
            if r.status_code == 200:
                return r.json()
            # 429/401/403: raise with info
            last_err = RuntimeError(f"Timeline HTTP {r.status_code}: {r.text[:300]}")
        except requests.RequestException as e:
            last_err = e
        if attempt < REQUEST_RETRIES:
            jitter_sleep(SLEEP_MIN, SLEEP_MAX)
        else:
            raise last_err
    # Should not reach here
    return {}

def download_image(session: requests.Session, url: str, dest_path: str):
    last_err = None
    for attempt in range(1, DOWNLOAD_RETRIES + 1):
        try:
            with session.get(url, stream=True, timeout=60) as r:
                if r.status_code != 200:
                    last_err = RuntimeError(f"Image HTTP {r.status_code} for {url}")
                else:
                    tmp = dest_path + ".part"
                    with open(tmp, "wb") as f:
                        for chunk in r.iter_content(chunk_size=1024 * 64):
                            if chunk:
                                f.write(chunk)
                    os.replace(tmp, dest_path)
                    return
        except requests.RequestException as e:
            last_err = e
        if attempt < DOWNLOAD_RETRIES:
            jitter_sleep(0.4, 1.2)
        else:
            raise last_err

# ----------------- Main flow -----------------
try:
    ensure_values()
    session = build_session(AUTH_TOKEN, CT0, WEB_BEARER)
    out_dir = make_output_dir(OUTPUT_DIR, USERNAME)

    # Track already-downloaded URLs
    archive_path = os.path.join(out_dir, "downloaded_urls.txt")
    downloaded: Set[str] = set()
    if os.path.exists(archive_path):
        with open(archive_path, "r", encoding="utf-8") as f:
            for line in f:
                u = line.strip()
                if u:
                    downloaded.add(u)

    cursor = None
    pages = 0
    found_total = 0
    saved_total = 0

    while pages < MAX_PAGES:
        pages += 1
        resp = timeline_request(session, USERNAME, cursor)
        photos = parse_photo_urls_from_search_adaptive(resp)
        found_total += len(photos)

        # Save images
        for tid, url in photos:
            if url in downloaded:
                continue
            fname = f"{tid}_{os.path.basename(url.split('?')[0])}"
            dest = os.path.join(out_dir, fname)
            try:
                download_image(session, url, dest)
                downloaded.add(url)
                saved_total += 1
            except Exception as e:
                print(f"[Download error] {e}")

        # Persist archive incrementally
        if photos:
            with open(archive_path, "a", encoding="utf-8") as f:
                for _, url in photos:
                    if url in downloaded:
                        f.write(url + "\n")

        next_cursor = extract_next_cursor(resp)
        if not next_cursor:
            print("No further cursor found; reached the end or response format changed.")
            break
        cursor = next_cursor
        jitter_sleep(SLEEP_MIN, SLEEP_MAX)

    print(f"Pages crawled: {pages}")
    print(f"Photo URLs found: {found_total}")
    print(f"Photos saved: {saved_total}")
    print("Saved to:", out_dir)
except Exception as e:
    print("[Fatal]", repr(e))
    raise
