Genetic algorithms (GAs) are simple, nature-inspired search methods that optimize by evolving a population of candidate solutions. Each generation, they select fitter candidates, recombine them (crossover), and randomly perturb them (mutation) to explore the space and gradually improve solutions. In finance and budgeting, GAs are useful for problems with non-linear objectives, hard constraints (like per-category bounds and weights summing to 1), and discrete or combinatorial choices. Benefits include flexibility and the ability to handle complex constraints; limitations include slower convergence than specialized convex solvers and the need to tune hyperparameters, with no guarantee of global optimality.

Walkthrough of the key parts in the Go implementation below:
- Objective: objective computes expected return minus lambda times variance (risk), using dot for returns and quadForm for w^T Σ w. This is the score the GA maximizes.
- Selection: tournamentSelect samples k random individuals and returns the one with the highest fitness, favoring fitter solutions.
- Crossover: uniformCrossover builds two children by picking each weight from parent1 or parent2 with 50% probability, recombining information from two solutions.
- Mutation: mutate adds small Gaussian noise to weights with a given per-gene probability, injecting diversity to escape local optima. We always repair solutions after mutation.
- Projection (constraint handling): projectToSimplexWithBounds enforces min/max per-asset bounds and the sum-to-1 constraint by projecting onto the bounded simplex via a bisection-based Lagrange multiplier method. After crossover/mutation, we project before reevaluating fitness.
- Main loop: For each generation, sort by fitness, keep elites, then repeatedly select parents, crossover, mutate, project (repair), and reevaluate fitness. Print progress and the final best solution.

Save as main.go and run with: go run main.go

```go
// main.go
package main

import (
	"fmt"
	"log"
	"math"
	"math/rand"
	"sort"
	"strings"
	"time"
)

type Individual struct {
	Weights []float64
	Fitness float64
}

func main() {
	rand.Seed(time.Now().UnixNano())

	// Example data: 5 assets (or budget categories)
	expectedReturns := []float64{0.12, 0.10, 0.07, 0.15, 0.09}
	cov := [][]float64{
		{0.10, 0.02, 0.04, 0.00, 0.01},
		{0.02, 0.08, 0.01, 0.03, 0.00},
		{0.04, 0.01, 0.12, 0.02, 0.02},
		{0.00, 0.03, 0.02, 0.15, 0.01},
		{0.01, 0.00, 0.02, 0.01, 0.09},
	}

	n := len(expectedReturns)

	// Per-asset bounds (e.g., min 0%, max 60%)
	minW := make([]float64, n)
	maxW := make([]float64, n)
	for i := 0; i < n; i++ {
		minW[i] = 0.0
		maxW[i] = 0.6
	}

	// GA hyperparameters
	popSize := 200
	generations := 300
	crossoverRate := 0.9
	mutationRate := 0.1
	mutationSigma := 0.05
	tournamentSize := 3
	elitism := 2

	// Risk aversion (lambda): higher penalizes variance more
	riskAversion := 0.5

	// Ensure feasibility of bounds
	sumMin := 0.0
	sumMax := 0.0
	for i := 0; i < n; i++ {
		sumMin += minW[i]
		sumMax += maxW[i]
	}
	if sumMin > 1.0+1e-9 || sumMax < 1.0-1e-9 {
		log.Fatalf("Infeasible bounds: sum(min)=%.6f, sum(max)=%.6f; cannot sum to 1", sumMin, sumMax)
	}

	// Initialize population
	pop := make([]Individual, popSize)
	for i := 0; i < popSize; i++ {
		w := randomFeasibleWeights(n, minW, maxW)
		f := objective(w, expectedReturns, cov, riskAversion)
		pop[i] = Individual{Weights: w, Fitness: f}
	}

	best := bestIndividual(pop)
	fmt.Println("Initial best fitness:", best.Fitness)
	fmt.Println("Initial weights:", pretty(best.Weights))

	for gen := 0; gen < generations; gen++ {
		// Sort population by fitness (descending)
		pop = sortByFitness(pop)

		// Keep elites
		nextPop := make([]Individual, 0, popSize)
		for i := 0; i < elitism && i < len(pop); i++ {
			nextPop = append(nextPop, copyIndividual(pop[i]))
		}

		// Generate rest via selection, crossover, mutation
		for len(nextPop) < popSize {
			parent1 := tournamentSelect(pop, tournamentSize)
			parent2 := tournamentSelect(pop, tournamentSize)

			child1 := copyIndividual(parent1)
			child2 := copyIndividual(parent2)

			if rand.Float64() < crossoverRate {
				child1, child2 = uniformCrossover(parent1, parent2)
			}

			mutate(&child1, mutationRate, mutationSigma)
			mutate(&child2, mutationRate, mutationSigma)

			// Repair and re-evaluate
			projectToSimplexWithBounds(child1.Weights, minW, maxW)
			child1.Fitness = objective(child1.Weights, expectedReturns, cov, riskAversion)

			projectToSimplexWithBounds(child2.Weights, minW, maxW)
			child2.Fitness = objective(child2.Weights, expectedReturns, cov, riskAversion)

			nextPop = append(nextPop, child1)
			if len(nextPop) < popSize {
				nextPop = append(nextPop, child2)
			}
		}

		pop = nextPop
		currentBest := bestIndividual(pop)

		// Simple logging
		if (gen+1)%25 == 0 || gen == generations-1 {
			fmt.Printf("Gen %d | Best fitness: %.6f | Weights: %s\n",
				gen+1, currentBest.Fitness, pretty(currentBest.Weights))
		}
	}

	// Final result
	pop = sortByFitness(pop)
	best = pop[0]
	fmt.Println("\nFinal best fitness:", best.Fitness)
	fmt.Println("Final weights:", pretty(best.Weights))
	fmt.Printf("Expected return: %.6f, Variance: %.6f\n",
		dot(best.Weights, expectedReturns),
		quadForm(best.Weights, cov))
}

