static std::string B64Decode(const std::string& in) {
    BIO* b64 = BIO_new(BIO_f_base64());
    BIO_set_flags(b64, BIO_FLAGS_BASE64_NO_NL);
    BIO* bio = BIO_new_mem_buf(in.data(), (int)in.size());
    bio = BIO_push(b64, bio);
    std::string out(in.size(), '\0');
    int n = BIO_read(bio, out.data(), (int)out.size());
    if (n < 0) n = 0;
    out.resize((size_t)n);
    BIO_free_all(bio);
    return out;
}

// Minimal base32 (lowercase) decode for .onion parsing
static int Base32Val(int c) {
    if (c >= 'a' && c <= 'z') return c - 'a';
    if (c >= '2' && c <= '7') return 26 + (c - '2');
    if (c >= 'A' && c <= 'Z') return c - 'A';
    return -1;
}

static bool Base32Decode(const std::string& in, std::vector<uint8_t>& out) {
    out.clear();
    int buffer = 0, bitsLeft = 0;
    for (char ch : in) {
        if (ch == '=') break;
        int val = Base32Val(ch);
        if (val < 0) return false;
        buffer = (buffer << 5) | val;
        bitsLeft += 5;
        if (bitsLeft >= 8) {
            bitsLeft -= 8;
            out.push_back((uint8_t)((buffer >> bitsLeft) & 0xFF));
        }
    }
    return true;
}

// URL parser for https://host[:port]/path
struct ParsedUrl { std::wstring host; INTERNET_PORT port{443}; std::wstring path{L"/"}; bool https{true}; };

static bool ParseHttpsUrl(const std::wstring& url, ParsedUrl& out) {
    out = ParsedUrl();
    const std::wstring https = L"https://";
    if (url.rfind(https, 0) != 0) return false;
    size_t pos = https.size();
    size_t slash = url.find(L'/', pos);
    std::wstring hostport = (slash == std::wstring::npos) ? url.substr(pos) : url.substr(pos, slash - pos);
    out.path = (slash == std::wstring::npos) ? L"/" : url.substr(slash);
    size_t colon = hostport.find(L':');
    if (colon == std::wstring::npos) {
        out.host = hostport;
        out.port = 443;
    } else {
        out.host = hostport.substr(0, colon);
        out.port = (INTERNET_PORT)std::stoi(hostport.substr(colon + 1));
    }
    out.https = true;
    return !out.host.empty();
}

// HTTP(S) GET and POST via WinHTTP
static bool HttpGet(const std::wstring& url, std::string& out_body, std::map<std::wstring,std::wstring>* resp_headers = nullptr) {
    out_body.clear();
    ParsedUrl u; if (!ParseHttpsUrl(url, u)) { std::wcerr << L"Invalid URL (expect https): " << url << L"\n"; return false; }
    WinHttpHandle hSession(WinHttpOpen(L"WinHTTP TorClient/1.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY, WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0));
    if (!hSession) { std::wcerr << L"WinHttpOpen failed: " << FormatLastError() << L"\n"; return false; }
    WinHttpHandle hConnect(WinHttpConnect(hSession, u.host.c_str(), u.port, 0));
    if (!hConnect) { std::wcerr << L"WinHttpConnect failed: " << FormatLastError() << L"\n"; return false; }
    DWORD flags = WINHTTP_FLAG_SECURE;
    WinHttpHandle hRequest(WinHttpOpenRequest(hConnect, L"GET", u.path.c_str(), nullptr, WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, flags));
    if (!hRequest) { std::wcerr << L"WinHttpOpenRequest failed: " << FormatLastError() << L"\n"; return false; }

    BOOL b = WinHttpSendRequest(hRequest, WINHTTP_NO_ADDITIONAL_HEADERS, 0, WINHTTP_NO_REQUEST_DATA, 0, 0, 0);
    if (!b) { std::wcerr << L"WinHttpSendRequest failed: " << FormatLastError() << L"\n"; return false; }
    b = WinHttpReceiveResponse(hRequest, nullptr);
    if (!b) { std::wcerr << L"WinHttpReceiveResponse failed: " << FormatLastError() << L"\n"; return false; }

    if (resp_headers) {
        DWORD dwSize = 0;
        WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX, WINHTTP_NO_OUTPUT_BUFFER, &dwSize, WINHTTP_NO_HEADER_INDEX);
        if (GetLastError() == ERROR_INSUFFICIENT_BUFFER) {
            std::wstring hdrs; hdrs.resize(dwSize/sizeof(wchar_t));
            if (WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX, &hdrs[0], &dwSize, WINHTTP_NO_HEADER_INDEX)) {
                std::wstringstream ss(hdrs);
                std::wstring line;
                while (std::getline(ss, line)) {
                    size_t colon = line.find(L':');
                    if (colon != std::wstring::npos) {
                        std::wstring name = line.substr(0, colon);
                        std::wstring value = line.substr(colon + 1);
                        while (!value.empty() && (value[0] == L' ' || value[0] == L'\t')) value.erase(value.begin());
                        (*resp_headers)[name] = value;
                    }
                }
            }
        }
    }

    std::string body;
    for (;;) {
        DWORD avail = 0;
        if (!WinHttpQueryDataAvailable(hRequest, &avail)) { std::wcerr << L"WinHttpQueryDataAvailable failed: " << FormatLastError() << L"\n"; return false; }
        if (!avail) break;
        std::string chunk; chunk.resize(avail);
        DWORD read = 0;
        if (!WinHttpReadData(hRequest, &chunk[0], avail, &read)) { std::wcerr << L"WinHttpReadData failed: " << FormatLastError() << L"\n"; return false; }
        chunk.resize(read);
        out_body.append(chunk);
    }
    return true;
}

static bool HttpPost(const std::wstring& url, const std::string& payload, const std::wstring& contentType, std::string& out_body) {
    out_body.clear();
    ParsedUrl u; if (!ParseHttpsUrl(url, u)) { std::wcerr << L"Invalid URL (expect https): " << url << L"\n"; return false; }
    WinHttpHandle hSession(WinHttpOpen(L"WinHTTP TorClient/1.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY, WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0));
    if (!hSession) { std::wcerr << L"WinHttpOpen failed: " << FormatLastError() << L"\n"; return false; }
    WinHttpHandle hConnect(WinHttpConnect(hSession, u.host.c_str(), u.port, 0));
    if (!hConnect) { std::wcerr << L"WinHttpConnect failed: " << FormatLastError() << L"\n"; return false; }
    DWORD flags = WINHTTP_FLAG_SECURE;
    WinHttpHandle hRequest(WinHttpOpenRequest(hConnect, L"POST", u.path.c_str(), nullptr, WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, flags));
    if (!hRequest) { std::wcerr << L"WinHttpOpenRequest failed: " << FormatLastError() << L"\n"; return false; }

    std::wstring hdr = L"Content-Type: " + contentType + L"\r\n";
    BOOL b = WinHttpSendRequest(hRequest, hdr.c_str(), (DWORD)hdr.size(), (LPVOID)payload.data(), (DWORD)payload.size(), (DWORD)payload.size(), 0);
    if (!b) { std::wcerr << L"WinHttpSendRequest failed: " << FormatLastError() << L"\n"; return false; }
    b = WinHttpReceiveResponse(hRequest, nullptr);
    if (!b) { std::wcerr << L"WinHttpReceiveResponse failed: " << FormatLastError() << L"\n"; return false; }

    for (;;) {
        DWORD avail = 0;
        if (!WinHttpQueryDataAvailable(hRequest, &avail)) { std::wcerr << L"WinHttpQueryDataAvailable failed: " << FormatLastError() << L"\n"; return false; }
        if (!avail) break;
        std::string chunk; chunk.resize(avail);
        DWORD read = 0;
        if (!WinHttpReadData(hRequest, &chunk[0], avail, &read)) { std::wcerr << L"WinHttpReadData failed: " << FormatLastError() << L"\n"; return false; }
        chunk.resize(read);
        out_body.append(chunk);
    }
    return true;
}

// Minimal Tor consensus text parser (extracts "r"/"s" lines and relays)
struct RelayInfo { std::string nickname; std::string identity; std::string address; int orport{0}; };

static std::vector<RelayInfo> ParseConsensus(const std::string& text) {
    std::vector<RelayInfo> relays;
    std::istringstream ss(text);
    std::string line;
    RelayInfo cur;
    while (std::getline(ss, line)) {
        if (!line.empty() && (line.back() == '\r')) line.pop_back();
        if (line.rfind("r ", 0) == 0) {
            std::istringstream ls(line);
            std::string tag; ls >> tag; // r
            cur = RelayInfo();
            ls >> cur.nickname;
            std::string ident_b64, digest_b64; ls >> ident_b64 >> digest_b64; // legacy fields
            ls >> cur.address; // IPv4 address
            int orport = 0, dirport = 0; ls >> orport >> dirport;
            cur.orport = orport;
            // identity (ed25519) is in separate "id" lines in newer formats; keep nickname/addr/orport
            relays.push_back(cur);
        }
        // s lines contain flags; ignored here.
    }
    return relays;
}

// v3 onion address decode: returns 32-byte ed25519 pubkey on success
static bool DecodeOnionV3Pubkey(const std::string& onion, std::vector<uint8_t>& pubkey32) {
    std::string name = onion;
    if (name.size() > 6 && name.rfind(".onion", name.size()-6) == name.size()-6) name = name.substr(0, name.size()-6);
    for (auto& c : name) c = (char)std::tolower((unsigned char)c);
    if (name.size() != 56) return false;
    std::vector<uint8_t> raw;
    if (!Base32Decode(name, raw)) return false;
    if (raw.size() != 35) return false; // 32 pubkey + 2 checksum + 1 version
    pubkey32.assign(raw.begin(), raw.begin()+32);
    uint8_t version = raw[34];
    if (version != 0x03) return false;
    return true;
}

// Minimal v3 HS descriptor parser (extract basic sections; does not verify signatures)
struct HSDescriptor {
    std::string hs_ed25519; // base64 key from descriptor
    std::vector<std::string> intro_points_raw; // raw base64-encoded intro points blocks
};

static HSDescriptor ParseHSDescriptor(const std::string& text) {
    HSDescriptor d;
    std::istringstream ss(text);
    std::string line;
    bool in_intro = false;
    std::ostringstream current_block;
    while (std::getline(ss, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.rfind("hs-ed25519-public-key", 0) == 0) {
            // Next line(s) until END block is base64 key, but many descriptors inline it on same line
            // Example: "hs-ed25519-public-key: AAAAA...."
            size_t pos = line.find(':');
            if (pos != std::string::npos) {
                std::string v = line.substr(pos+1);
                while (!v.empty() && (v[0]==' '||v[0]=='\t')) v.erase(v.begin());
                d.hs_ed25519 = v;
            }
        } else if (line.rfind("introduction-points", 0) == 0) {
            in_intro = true;
            current_block.str(""); current_block.clear();
        } else if (in_intro && line == "-----END MESSAGE-----") {
            d.intro_points_raw.push_back(current_block.str());
            in_intro = false;
            current_block.str(""); current_block.clear();
        } else if (in_intro) {
            current_block << line << "\n";
        }
    }
    return d;
}

// Download helpers for Tor documents hosted via HTTPS mirrors
static bool DownloadConsensus(const std::wstring& consensus_url, std::string& out_text, std::vector<RelayInfo>& out_relays) {
    std::map<std::wstring,std::wstring> headers;
    if (!HttpGet(consensus_url, out_text, &headers)) return false;
    out_relays = ParseConsensus(out_text);
    return true;
}

static bool DownloadHSDescriptor(const std::wstring& descriptor_url, std::string& out_text, HSDescriptor& out_desc) {
    if (!HttpGet(descriptor_url, out_text, nullptr)) return false;
    out_desc = ParseHSDescriptor(out_text);
    return true;
}

// Perform HTTPS GET/POST to an HTTPS endpoint
static void DemoHttp(const std::wstring& get_url, const std::wstring& post_url, const std::string& post_body) {
    std::string body;
    if (!get_url.empty()) {
        if (HttpGet(get_url, body)) {
            std::wcout << L"GET OK: " << get_url << L"\nBytes: " << body.size() << L"\n";
        } else {
            std::wcout << L"GET failed: " << get_url << L"\n";
        }
    }
    if (!post_url.empty()) {
        std::string resp;
        if (HttpPost(post_url, post_body, L"application/x-www-form-urlencoded", resp)) {
            std::wcout << L"POST OK: " << post_url << L"\nBytes: " << resp.size() << L"\n";
        } else {
            std::wcout << L"POST failed: " << post_url << L"\n";
        }
    }
}

// Attempt to treat a .onion as an HTTPS host (will not resolve without Tor, included per request)
static bool HttpGetOnion(const std::string& onion_host, const std::wstring& path, std::string& out_body) {
    // Build https://<onion>/<path>
    std::wstring url = L"https://" + Utf8ToWide(onion_host) + path;
    return HttpGet(url, out_body);
}

static bool HttpPostOnion(const std::string& onion_host, const std::wstring& path, const std::string& payload, const std::wstring& contentType, std::string& out_body) {
    std::wstring url = L"https://" + Utf8ToWide(onion_host) + path;
    return HttpPost(url, payload, contentType, out_body);
}

int wmain(int argc, wchar_t** argv) {
    OpenSSLGlobalInit openssl_init;

    std::wstring consensus_url;
    std::wstring descriptor_url;
    std::wstring get_url;
    std::wstring post_url;
    std::string post_body;
    std::string onion_host; // e.g., exampleonionaddress.onion
    std::wstring onion_get_path = L"/";
    std::wstring onion_post_path = L"/";
    std::string onion_post_body;

    for (int i = 1; i < argc; ++i) {
        std::wstring arg = argv[i];
        if (arg == L"--consensus-url" && i+1 < argc) { consensus_url = argv[++i]; }
        else if (arg == L"--descriptor-url" && i+1 < argc) { descriptor_url = argv[++i]; }
        else if (arg == L"--get" && i+1 < argc) { get_url = argv[++i]; }
        else if (arg == L"--post" && i+2 < argc) { post_url = argv[++i]; post_body = WideToUtf8(argv[++i]); }
        else if (arg == L"--onion" && i+1 < argc) { onion_host = WideToUtf8(argv[++i]); }
        else if (arg == L"--onion-get-path" && i+1 < argc) { onion_get_path = argv[++i]; }
        else if (arg == L"--onion-post-path" && i+2 < argc) { onion_post_path = argv[++i]; onion_post_body = WideToUtf8(argv[++i]); }
    }

    if (!consensus_url.empty()) {
        std::string consensus_text; std::vector<RelayInfo> relays;
        if (DownloadConsensus(consensus_url, consensus_text, relays)) {
            std::wcout << L"Consensus downloaded. Size=" << consensus_text.size() << L" bytes, relays parsed=" << relays.size() << L"\n";
            size_t show = std::min<size_t>(relays.size(), 5);
            for (size_t i = 0; i < show; ++i) {
                std::wcout << L"  Relay " << i+1 << L": nickname=" << Utf8ToWide(relays[i].nickname)
                           << L" addr=" << Utf8ToWide(relays[i].address) << L" orport=" << relays[i].orport << L"\n";
            }
        } else {
            std::wcout << L"Failed to download/parse consensus\n";
        }
    }

    if (!descriptor_url.empty()) {
        std::string desc_text; HSDescriptor desc;
        if (DownloadHSDescriptor(descriptor_url, desc_text, desc)) {
            std::wcout << L"Descriptor downloaded. Size=" << desc_text.size() << L" bytes\n";
            std::wcout << L"hs-ed25519-public-key (base64, if present): " << Utf8ToWide(desc.hs_ed25519) << L"\n";
            std::wcout << L"introduction-points blocks: " << desc.intro_points_raw.size() << L"\n";
        } else {
            std::wcout << L"Failed to download/parse descriptor\n";
        }
    }

    if (!get_url.empty() || !post_url.empty()) {
        DemoHttp(get_url, post_url, post_body);
    }

    if (!onion_host.empty()) {
        std::vector<uint8_t> pubkey;
        if (DecodeOnionV3Pubkey(onion_host, pubkey)) {
            std::wcout << L"Parsed .onion v3 pubkey (32 bytes).\n";
        } else {
            std::wcout << L"Invalid .onion v3 address format: " << Utf8ToWide(onion_host) << L"\n";
        }
        if (!onion_get_path.empty()) {
            std::string body;
            bool ok = HttpGetOnion(onion_host, onion_get_path, body);
            std::wcout << L"Onion GET " << (ok ? L"attempted (bytes=" + std::to_wstring(body.size()) + L")" : L"failed") << L" on https://" << Utf8ToWide(onion_host) << onion_get_path << L"\n";
        }
        if (!onion_post_path.empty()) {
            std::string body;
            bool ok = HttpPostOnion(onion_host, onion_post_path, onion_post_body, L"application/x-www-form-urlencoded", body);
            std::wcout << L"Onion POST " << (ok ? L"attempted (bytes=" + std::to_wstring(body.size()) + L")" : L"failed") << L" on https://" << Utf8ToWide(onion_host) << onion_post_path << L"\n";
        }
    }

    return 0;
}

