static std::string ToLower(std::string s) {
    std::transform(s.begin(), s.end(), s.begin(), [](unsigned char c){ return (char)std::tolower(c); });
    return s;
}

static bool Base32NoPadDecode(const std::string& in, std::vector<uint8_t>& out) {
    static const int8_t map[256] = {
        -1
    };
    static bool init = false;
    static int8_t t[256];
    if (!init) {
        std::fill(std::begin(t), std::end(t), -1);
        const std::string alphabet = "abcdefghijklmnopqrstuvwxyz234567";
        for (size_t i = 0; i < alphabet.size(); ++i) t[(unsigned char)alphabet[i]] = (int8_t)i;
        init = true;
    }
    out.clear();
    int buffer = 0, bitsLeft = 0;
    for (char ch : ToLower(in)) {
        if (ch == '=') break;
        int8_t val = t[(unsigned char)ch];
        if (val < 0) continue;
        buffer = (buffer << 5) | val;
        bitsLeft += 5;
        if (bitsLeft >= 8) {
            out.push_back((uint8_t)((buffer >> (bitsLeft - 8)) & 0xFF));
            bitsLeft -= 8;
        }
    }
    return true;
}

struct Relay {
    std::string nickname;
    std::string identity;
    std::string ipv4;
    int orport{0};
    bool guard{false};
    bool exit{false};
};

struct Consensus {
    std::vector<Relay> relays;
};

static Consensus ParseConsensus(const std::string& text) {
    Consensus c;
    std::istringstream iss(text);
    std::string line;
    Relay current;
    bool in_router = false;
    while (std::getline(iss, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.rfind("r ", 0) == 0) {
            std::istringstream ls(line.substr(2));
            ls >> current.nickname;
            std::string ident_b64, digest_b64, published, ip; int orport = 0, dirport = 0;
            ls >> ident_b64 >> digest_b64 >> published >> ip >> orport >> dirport;
            current.identity = ident_b64;
            current.ipv4 = ip;
            current.orport = orport;
            current.guard = false; current.exit = false;
            in_router = true;
        } else if (in_router && line.rfind("s ", 0) == 0) {
            std::istringstream ls(line.substr(2));
            std::string flag;
            while (ls >> flag) {
                if (flag == "Guard") current.guard = true;
                if (flag == "Exit") current.exit = true;
            }
            c.relays.push_back(current);
            in_router = false;
        }
    }
    return c;
}

struct HSIntroPoint {
    std::string ip_addr;
    int orport{0};
};

struct HSDescriptor {
    std::string blinded_key_b32;
    std::vector<HSIntroPoint> intro_points;
};

static HSDescriptor ParseHSDescriptor(const std::string& text) {
    HSDescriptor d;
    std::istringstream iss(text);
    std::string line;
    bool in_intro = false;
    while (std::getline(iss, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.rfind("hs-descriptor 3", 0) == 0) {
            continue;
        } else if (line.rfind("descriptor-signing-key", 0) == 0) {
            continue;
        } else if (line.rfind("blinded-key", 0) == 0) {
            // Next line usually contains the key in PEM-like block; here we look for base32 on same/next lines
            // This is a simplified extractor for demonstration.
        } else if (line.rfind("introduction-point", 0) == 0) {
            in_intro = true;
            d.intro_points.emplace_back();
        } else if (in_intro && line.rfind("introduction-point", 0) == 0) {
            d.intro_points.emplace_back();
        } else if (in_intro && line.rfind("ip-address ", 0) == 0) {
            d.intro_points.back().ip_addr = line.substr(std::string("ip-address ").size());
        } else if (in_intro && line.rfind("or-port ", 0) == 0) {
            d.intro_points.back().orport = std::stoi(line.substr(std::string("or-port ").size()));
        } else if (line.rfind("signature", 0) == 0) {
            in_intro = false;
        }
    }
    return d;
}

static bool ValidateV3Onion(const std::string& onion) {
    std::string name = onion;
    if (name.size() > 6 && name.rfind(".onion") == name.size() - 6) {
        name = name.substr(0, name.size() - 6);
    }
    if (name.size() != 56) return false;
    for (char ch : name) {
        bool ok = (ch >= 'a' && ch <= 'z') || (ch >= '2' && ch <= '7');
        if (!ok) return false;
    }
    std::vector<uint8_t> dec;
    if (!Base32NoPadDecode(name, dec)) return false;
    if (dec.size() != 35) return false; // 32 pubkey + 2 checksum + 1 version
    if (dec.back() != 3) return false;
    return true;
}

static bool DownloadConsensus(const std::wstring& url, Consensus& out) {
    std::string body;
    if (!HttpGet(url, body)) return false;
    out = ParseConsensus(body);
    return true;
}

static bool DownloadHSDescriptor(const std::wstring& url, HSDescriptor& out) {
    std::string body;
    if (!HttpGet(url, body)) return false;
    out = ParseHSDescriptor(body);
    return true;
}

static bool PerformOnionGet(const std::wstring& url, std::string& out_body) {
    return HttpGet(url, out_body);
}

static bool PerformOnionPost(const std::wstring& url, const std::string& data, std::string& out_body) {
    return HttpPost(url, data, out_body);
}

static void PrintConsensusSummary(const Consensus& c) {
    std::cout << "Relays: " << c.relays.size() << "\n";
    size_t guards = 0, exits = 0;
    for (const auto& r : c.relays) { if (r.guard) ++guards; if (r.exit) ++exits; }
    std::cout << "Guards: " << guards << ", Exits: " << exits << "\n";
}

static void PrintHSSummary(const HSDescriptor& d) {
    std::cout << "Intro points: " << d.intro_points.size() << "\n";
    for (const auto& ip : d.intro_points) {
        std::cout << "  " << ip.ip_addr << ":" << ip.orport << "\n";
    }
}

static void Usage() {
    std::cout << "Options:\n"
                 "  --consensus-url <https-url>          Download and parse Tor consensus\n"
                 "  --descriptor-url <https-url>         Download and parse v3 HS descriptor\n"
                 "  --onion-get <https-url-to-.onion>    Perform GET to .onion URL\n"
                 "  --onion-post <https-url-to-.onion> <data>  Perform POST to .onion URL\n"
                 "  --onion-check <name.onion>           Validate v3 onion address\n";
}

int wmain(int argc, wchar_t** argv) {
    OpenSSLInit();

    if (argc <= 1) { Usage(); OpenSSLUninit(); return 0; }

    std::map<std::wstring, std::wstring> args;
    for (int i = 1; i < argc; ++i) {
        std::wstring k = argv[i];
        if ((k == L"--onion-post") && i + 2 < argc) {
            // handled later due to extra arg
        } else if (i + 1 < argc) {
            args[k] = argv[i + 1];
            ++i;
        } else {
            args[k] = L"";
        }
    }

    if (args.count(L"--consensus-url")) {
        Consensus c; if (DownloadConsensus(args[L"--consensus-url"], c)) {
            PrintConsensusSummary(c);
        } else {
            std::wcerr << L"Failed to download/parse consensus\n";
        }
    }

    if (args.count(L"--descriptor-url")) {
        HSDescriptor d; if (DownloadHSDescriptor(args[L"--descriptor-url"], d)) {
            PrintHSSummary(d);
        } else {
            std::wcerr << L"Failed to download/parse descriptor\n";
        }
    }

    for (int i = 1; i < argc; ++i) {
        std::wstring k = argv[i];
        if (k == L"--onion-get" && i + 1 < argc) {
            std::wstring url = argv[++i];
            std::string body;
            if (PerformOnionGet(url, body)) {
                std::cout << body << "\n";
            } else {
                std::wcerr << L"GET failed for " << url << L"\n";
            }
        } else if (k == L"--onion-post" && i + 2 < argc) {
            std::wstring url = argv[++i];
            std::string data = WideToUtf8(argv[++i]);
            std::string body;
            if (PerformOnionPost(url, data, body)) {
                std::cout << body << "\n";
            } else {
                std::wcerr << L"POST failed for " << url << L"\n";
            }
        }
    }

    if (args.count(L"--onion-check")) {
        std::string name = WideToUtf8(args[L"--onion-check"]);
        bool ok = ValidateV3Onion(name);
        std::cout << (ok ? "valid" : "invalid") << "\n";
    }

    OpenSSLUninit();
    return 0;
}

//+------------------------------------------------------------------+
//|                                       EMA_RSI_ATR_Manager.mq5    |
//|   EMA Cross + RSI + ATR with robust risk & margin management     |
//|   One-position-per-symbol, spread/session filters, trailing SL   |
//+------------------------------------------------------------------+
#property strict
#property version   "1.10"
#property description "EMA Cross + RSI + ATR strategy with complete trade management and robust margin/risk logic."

#include <Trade/Trade.mqh>

CTrade trade;

//========================
// Inputs: Strategy & Risk
//========================
input ENUM_TIMEFRAMES InpTimeframe      = PERIOD_M5;      // Signal timeframe
input int             InpFastEMA        = 21;             // Fast EMA period
input int             InpSlowEMA        = 55;             // Slow EMA period
input int             InpRSIPeriod      = 14;             // RSI period
input double          InpRSI_Buy        = 55.0;           // RSI threshold for buys
input double          InpRSI_Sell       = 45.0;           // RSI threshold for sells
input int             InpATRPeriod      = 14;             // ATR period
input double          InpATR_SL_Mult    = 1.5;            // SL = ATR * this multiplier
input double          InpATR_TrailMult  = 1.0;            // Trailing distance = ATR * this multiplier
input double          InpRR             = 2.0;            // Reward:Risk ratio
input double          InpATR_MinFilter  = 0.0;            // Minimum ATR filter (price units); set 0 to disable

//========================
// Inputs: Risk Management
//========================
input double          InpRiskPerTradePct          = 0.5;   // Percent of equity to risk per trade
input double          InpMaxFreeMarginUsagePct     = 10.0;  // Cap: single trade margin <= this % of free margin
input double          InpMinMarginLevelPct         = 500.0; // Do not open if current margin level below this (%); ignored if <=0 or margin level unavailable
input ulong           InpMagicNumber               = 987654321; // Magic number to tag positions

//========================
// Inputs: Execution & Filters
//========================
input int             InpSlippagePoints            = 20;    // Max deviation (points)
input int             InpMaxSpreadPoints           = 30;    // Max spread (points) allowed for entries
input string          InpSkipHoursUTC              = "21,22";// Skip trading on these UTC hours (comma-separated)
input bool            InpAllowTrailing             = true;  // Enable trailing SL
input double          InpBreakevenRR               = 1.0;   // Move SL to BE after reaching this RR (0 to disable)

//========================
// Internal state & handles
//========================
int     hFastEMA = INVALID_HANDLE;
int     hSlowEMA = INVALID_HANDLE;
int     hRSI     = INVALID_HANDLE;
int     hATR     = INVALID_HANDLE;

datetime gLastClosedBarTime = 0;

// Symbol parameters cache
double  gPoint      = 0.0;
int     gDigits     = 0;
double  gTickSize   = 0.0;
double  gTickValue  = 0.0;
double  gMinVolume  = 0.0;
double  gMaxVolume  = 0.0;
double  gVolStep    = 0.0;
int     gStopsLevelPoints = 0;
int     gFreezeLevelPoints = 0;

// Session skip hours (UTC)
bool    gSkipHour[24];

//----------------------------------------------------------------------
// Utility: Parse skip hours string to bool map
//----------------------------------------------------------------------
void ParseSkipHours(const string hours_csv)
{
  ArrayInitialize(gSkipHour,false);
  string trimmed = StringTrim(hours_csv);
  if(trimmed=="") return;
  string parts[];
  int n = StringSplit(trimmed, ',', parts);
  for(int i=0;i<n;i++)
  {
    string p = StringTrim(parts[i]);
    if(p=="") continue;
    int h = (int)StringToInteger(p);
    if(h>=0 && h<24) gSkipHour[h]=true;
  }
}

//----------------------------------------------------------------------
// Utility: Refresh and cache symbol trading info
//----------------------------------------------------------------------
bool RefreshSymbolInfo(const string sym)
{
  gPoint = SymbolInfoDouble(sym, SYMBOL_POINT);
  gDigits = (int)SymbolInfoInteger(sym, SYMBOL_DIGITS);
  gTickSize = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_SIZE);
  gTickValue = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_VALUE);
  gMinVolume = SymbolInfoDouble(sym, SYMBOL_VOLUME_MIN);
  gMaxVolume = SymbolInfoDouble(sym, SYMBOL_VOLUME_MAX);
  gVolStep = SymbolInfoDouble(sym, SYMBOL_VOLUME_STEP);
  gStopsLevelPoints = (int)SymbolInfoInteger(sym, SYMBOL_TRADE_STOPS_LEVEL);
  gFreezeLevelPoints = (int)SymbolInfoInteger(sym, SYMBOL_TRADE_FREEZE_LEVEL);

  if(gPoint<=0 || gTickSize<=0 || gTickValue<=0 || gMinVolume<=0 || gVolStep<=0)
  {
    PrintFormat("Symbol info invalid: point=%.10f ticksize=%.10f tickvalue=%.10f minvol=%.2f volstep=%.2f",
                gPoint, gTickSize, gTickValue, gMinVolume, gVolStep);
    return false;
  }
  return true;
}

//----------------------------------------------------------------------
// Utility: Normalize lot volume to broker step
//----------------------------------------------------------------------
double NormalizeVolume(double vol)
{
  if(vol<=0) return 0.0;
  double steps = MathFloor(vol / gVolStep + 1e-8);
  double v = steps * gVolStep;
  if(v < gMinVolume) v = 0.0;
  if(v > gMaxVolume) v = gMaxVolume;
  // Use 2 decimals for safety across most brokers; adjust if needed
  return NormalizeDouble(v, (int)MathMax(2, (int)MathRound(-MathLog10(gVolStep))));
}

//----------------------------------------------------------------------
// Utility: Normalize price to symbol digits
//----------------------------------------------------------------------
double NormalizePrice(double price)
{
  return NormalizeDouble(price, gDigits);
}

//----------------------------------------------------------------------
// Utility: Check if any open position exists for this symbol (any magic)
//----------------------------------------------------------------------
bool HasAnyPositionOnSymbol(const string sym)
{
  int total = PositionsTotal();
  for(int i=0;i<total;i++)
  {
    if(!PositionSelectByIndex(i)) continue;
    if(PositionGetString(POSITION_SYMBOL) == sym)
      return true;
  }
  return false;
}

//----------------------------------------------------------------------
// Utility: Find our own (magic) position on this symbol
//----------------------------------------------------------------------
bool GetOurPosition(const string sym, ulong &ticketOut, long &typeOut, double &priceOpenOut, double &slOut, double &tpOut, double &volumeOut)
{
  ticketOut = 0;
  typeOut = -1;
  slOut = 0; tpOut=0; volumeOut=0; priceOpenOut=0;
  int total = PositionsTotal();
  for(int i=0;i<total;i++)
  {
    if(!PositionSelectByIndex(i)) continue;
    if(PositionGetString(POSITION_SYMBOL) != sym) continue;
    if((ulong)PositionGetInteger(POSITION_MAGIC) != InpMagicNumber) continue;

    ticketOut = (ulong)PositionGetInteger(POSITION_TICKET);
    typeOut   = (long)PositionGetInteger(POSITION_TYPE);
    priceOpenOut = PositionGetDouble(POSITION_PRICE_OPEN);
    slOut = PositionGetDouble(POSITION_SL);
    tpOut = PositionGetDouble(POSITION_TP);
    volumeOut = PositionGetDouble(POSITION_VOLUME);
    return true;
  }
  return false;
}

//----------------------------------------------------------------------
// Utility: Market session/time filters
//----------------------------------------------------------------------
bool IsTradingAllowedNow()
{
  datetime now = TimeCurrent();
  MqlDateTime mt;
  TimeToStruct(now, mt);
  // Convert to UTC hour (TimeCurrent is usually server time; assume server time is UTC for simplicity).
  int hourUTC = mt.hour; // If broker not UTC, adjust with offset input in production.
  if(hourUTC>=0 && hourUTC<24 && gSkipHour[hourUTC])
    return false;
  return true;
}

//----------------------------------------------------------------------
// Utility: Spread filter in points
//----------------------------------------------------------------------
bool SpreadOK(const string sym)
{
  MqlTick tick;
  if(!SymbolInfoTick(sym, tick)) return false;
  double spread_points = (tick.ask - tick.bid) / gPoint;
  return (spread_points <= InpMaxSpreadPoints);
}

//----------------------------------------------------------------------
// Indicators: Ensure handles and data
//----------------------------------------------------------------------
bool EnsureIndicators(const string sym)
{
  if(hFastEMA==INVALID_HANDLE)
    hFastEMA = iMA(sym, InpTimeframe, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
  if(hSlowEMA==INVALID_HANDLE)
    hSlowEMA = iMA(sym, InpTimeframe, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
  if(hRSI==INVALID_HANDLE)
    hRSI = iRSI(sym, InpTimeframe, InpRSIPeriod, PRICE_CLOSE);
  if(hATR==INVALID_HANDLE)
    hATR = iATR(sym, InpTimeframe, InpATRPeriod);

  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
  {
    Print("Indicator handle creation failed.");
    return false;
  }

  // Check enough data
  if(BarsCalculated(hFastEMA)<MathMax(InpFastEMA,100) ||
     BarsCalculated(hSlowEMA)<MathMax(InpSlowEMA,100) ||
     BarsCalculated(hRSI)<MathMax(InpRSIPeriod,100)   ||
     BarsCalculated(hATR)<MathMax(InpATRPeriod,100))
  {
    Print("Indicators not fully calculated yet.");
    return false;
  }
  return true;
}

//----------------------------------------------------------------------
// Signal logic (EMA cross + RSI filter). Execute on bar close
//----------------------------------------------------------------------
int Signal(const string sym, double &atrOut)
{
  atrOut = 0.0;
  if(!EnsureIndicators(sym)) return 0;

  // Read last two closed bars
  int shift1 = 1; // last closed bar
  int shift2 = 2; // previous bar

  double emaFast1[], emaFast2[];
  double emaSlow1[], emaSlow2[];
  double rsi1[], rsi2[];
  double atr1[];

  ArraySetAsSeries(emaFast1,true); ArraySetAsSeries(emaSlow1,true);
  ArraySetAsSeries(rsi1,true);     ArraySetAsSeries(atr1,true);

  if(CopyBuffer(hFastEMA,0,shift1,2,emaFast1)!=2) return 0;
  if(CopyBuffer(hSlowEMA,0,shift1,2,emaSlow1)!=2) return 0;
  if(CopyBuffer(hRSI,0,shift1,2,rsi1)!=2) return 0;
  if(CopyBuffer(hATR,0,shift1,1,atr1)!=1) return 0;

  double f1 = emaFast1[0];
  double f2 = emaFast1[1];
  if(CopyBuffer(hFastEMA,0,shift2,1,emaFast2)!=1) return 0; // ensure previous
  double s1 = emaSlow1[0];
  double s2 = emaSlow1[1];
  if(CopyBuffer(hSlowEMA,0,shift2,1,emaSlow2)!=1) return 0;
  double r1 = rsi1[0];
  if(CopyBuffer(hRSI,0,shift2,1,rsi2)!=1) return 0;
  atrOut = atr1[0];

  if(InpATR_MinFilter>0.0 && atrOut < InpATR_MinFilter)
    return 0;

  // Cross up: fast crosses above slow and RSI confirms
  bool crossUp   = (f2 <= s2) && (f1 > s1) && (r1 >= InpRSI_Buy);
  bool crossDown = (f2 >= s2) && (f1 < s1) && (r1 <= InpRSI_Sell);

  if(crossUp) return 1;
  if(crossDown) return -1;
  return 0;
}

//----------------------------------------------------------------------
// Risk and margin checks + position sizing using equity and ATR-based SL
//----------------------------------------------------------------------
bool ComputeOrder(const string sym, const int dir, const double atr, double &volume, double &sl, double &tp, string &why)
{
  volume = 0.0; sl=0.0; tp=0.0; why="";

  if(atr<=0.0)
  {
    why = "ATR non-positive"; return false;
  }

  MqlTick tick; if(!SymbolInfoTick(sym, tick)) { why="No tick"; return false; }
  double price = (dir>0) ? tick.ask : tick.bid;

  // Compute SL distance from ATR
  double sl_dist = InpATR_SL_Mult * atr;
  if(sl_dist <= gPoint * (gStopsLevelPoints + gFreezeLevelPoints + 2))
  {
    sl_dist = gPoint * (gStopsLevelPoints + gFreezeLevelPoints + 2);
  }

  // Proposed SL/TP prices
  if(dir>0)
  {
    sl = NormalizePrice(price - sl_dist);
    double tp_dist = InpRR * sl_dist;
    tp = NormalizePrice(price + tp_dist);
  }
  else
  {
    sl = NormalizePrice(price + sl_dist);
    double tp_dist = InpRR * sl_dist;
    tp = NormalizePrice(price - tp_dist);
  }

  // Equity-based risk sizing: risk = equity * pct
  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  double risk_amount = equity * (InpRiskPerTradePct/100.0);
  if(risk_amount <= 0.0)
  {
    why = "Risk amount <= 0"; return false;
  }

  // Estimate ticks to SL and per-lot loss at SL using tick value
  double sl_ticks = MathMax(1.0, sl_dist / gTickSize);
  double loss_per_lot = sl_ticks * gTickValue; // approximate
  if(loss_per_lot <= 0.0)
  {
    why = "Loss per lot calc invalid"; return false;
  }

  double raw_volume = risk_amount / loss_per_lot;
  volume = NormalizeVolume(raw_volume);
  if(volume <= 0.0)
  {
    why = "Volume normalized to 0 (risk too small or broker limits)"; return false;
  }

  // Margin calculation and caps
  double margin_per_lot = 0.0;
  if(!OrderCalcMargin((dir>0)?ORDER_TYPE_BUY:ORDER_TYPE_SELL, sym, volume, price, margin_per_lot))
  {
    why = "OrderCalcMargin failed: " + IntegerToString(GetLastError());
    return false;
  }

  double free_margin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(free_margin <= 0.0)
  {
    why = "Free margin <= 0"; return false;
  }

  // Per-trade margin cap as percent of free margin
  double max_margin_allowed = free_margin * (InpMaxFreeMarginUsagePct/100.0);
  if(margin_per_lot > max_margin_allowed)
  {
    // Try reduce volume proportionally
    double scale = max_margin_allowed / margin_per_lot;
    double v2 = NormalizeVolume(volume * scale);
    if(v2 < gMinVolume)
    {
      why = "Margin cap reduces volume below min"; return false;
    }
    volume = v2;
    if(!OrderCalcMargin((dir>0)?ORDER_TYPE_BUY:ORDER_TYPE_SELL, sym, volume, price, margin_per_lot))
    {
      why = "OrderCalcMargin after resize failed: " + IntegerToString(GetLastError());
      return false;
    }
  }

  // Validate margin level (%): (Equity / MarginUsed) * 100
  double margin_level = AccountInfoDouble(ACCOUNT_MARGIN_LEVEL); // may be 0 if no positions
  if(InpMinMarginLevelPct>0.0 && margin_level>0.0)
  {
    // Estimate new margin level if this trade opens
    double margin_used_now = AccountInfoDouble(ACCOUNT_MARGIN);
    double equity_now = equity;
    double margin_used_new = margin_used_now + margin_per_lot;
    double level_new = (margin_used_new>0.0) ? (equity_now / margin_used_new) * 100.0 : 0.0;
    if(level_new < InpMinMarginLevelPct)
    {
      why = StringFormat("Projected margin level %.1f%% < min %.1f%%", level_new, InpMinMarginLevelPct);
      return false;
    }
  }

  // Final sanity: stops level distance
  if(dir>0)
  {
    if((price - sl) < (gStopsLevelPoints * gPoint)) { why = "SL within stops level"; return false; }
    if((tp - price) < (gStopsLevelPoints * gPoint)) { why = "TP within stops level"; return false; }
  }
  else
  {
    if((sl - price) < (gStopsLevelPoints * gPoint)) { why = "SL within stops level"; return false; }
    if((price - tp) < (gStopsLevelPoints * gPoint)) { why = "TP within stops level"; return false; }
  }

  return true;
}

//----------------------------------------------------------------------
// Trade executor
//----------------------------------------------------------------------
bool OpenPosition(const string sym, const int dir, const double volume, const double sl, const double tp, string &why)
{
  MqlTick tick; if(!SymbolInfoTick(sym, tick)) { why="No tick"; return false; }
  double price = (dir>0) ? tick.ask : tick.bid;

  trade.SetExpertMagicNumber(InpMagicNumber);
  trade.SetTypeFillingBySymbol(sym);
  trade.SetDeviationInPoints(InpSlippagePoints);

  bool ok=false;
  if(dir>0)
    ok = trade.Buy(volume, sym, price, sl, tp, "EMA/RSI Buy");
  else
    ok = trade.Sell(volume, sym, price, sl, tp, "EMA/RSI Sell");

  if(!ok)
  {
    int err = GetLastError();
    why = StringFormat("Order send failed (%d): %s", err, ErrorDescription(err));
    ResetLastError();
    return false;
  }
  return true;
}

//----------------------------------------------------------------------
// Trailing stop and breakeven management
//----------------------------------------------------------------------
void ManagePosition(const string sym, const long type, const double atr)
{
  if(!InpAllowTrailing) return;
  if(atr<=0.0) return;

  double trail_dist = InpATR_TrailMult * atr;
  if(trail_dist <= gPoint * (gStopsLevelPoints + 2))
    trail_dist = gPoint * (gStopsLevelPoints + 2);

  if(!PositionSelect(sym)) return;
  if((ulong)PositionGetInteger(POSITION_MAGIC) != InpMagicNumber) return;

  double open_price = PositionGetDouble(POSITION_PRICE_OPEN);
  double sl = PositionGetDouble(POSITION_SL);
  double tp = PositionGetDouble(POSITION_TP);
  double volume = PositionGetDouble(POSITION_VOLUME);

  MqlTick tick; if(!SymbolInfoTick(sym, tick)) return;

  // Breakeven move
  if(InpBreakevenRR>0.0)
  {
    double initial_risk = (type==POSITION_TYPE_BUY) ? (open_price - sl) : (sl - open_price);
    if(initial_risk>0.0)
    {
      double rr_price = (type==POSITION_TYPE_BUY) ? (open_price + InpBreakevenRR*initial_risk)
                                                  : (open_price - InpBreakevenRR*initial_risk);
      if((type==POSITION_TYPE_BUY && tick.bid >= rr_price) ||
         (type==POSITION_TYPE_SELL && tick.ask <= rr_price))
      {
        double be_sl = (type==POSITION_TYPE_BUY) ? NormalizePrice(open_price + gPoint* (gStopsLevelPoints+1))
                                                 : NormalizePrice(open_price - gPoint* (gStopsLevelPoints+1));
        if((type==POSITION_TYPE_BUY && (sl < be_sl)) || (type==POSITION_TYPE_SELL && (sl > be_sl)))
        {
          trade.PositionModify(sym, be_sl, tp);
        }
      }
    }
  }

  // ATR trailing
  if(type==POSITION_TYPE_BUY)
  {
    double new_sl = NormalizePrice(tick.bid - trail_dist);
    if(new_sl > sl)
    {
      // ensure not beyond TP and respects stops level
      if((tp==0.0 || new_sl < tp) && (tick.bid - new_sl) >= gStopsLevelPoints*gPoint)
        trade.PositionModify(sym, new_sl, tp);
    }
  }
  else if(type==POSITION_TYPE_SELL)
  {
    double new_sl = NormalizePrice(tick.ask + trail_dist);
    if(new_sl < sl || sl==0.0)
    {
      if((tp==0.0 || new_sl > tp) && (new_sl - tick.ask) >= gStopsLevelPoints*gPoint)
        trade.PositionModify(sym, new_sl, tp);
    }
  }
}

//----------------------------------------------------------------------
// OnInit: prepare indicators and environment
//----------------------------------------------------------------------
int OnInit()
{
  const string sym = _Symbol;
  if(!RefreshSymbolInfo(sym))
  {
    Print("Initialization failed: bad symbol info");
    return(INIT_FAILED);
  }

  ParseSkipHours(InpSkipHoursUTC);

  if(!EnsureIndicators(sym))
  {
    Print("Initialization waiting for indicators");
  }

  gLastClosedBarTime = 0;
  return(INIT_SUCCEEDED);
}

//----------------------------------------------------------------------
// OnTick: main execution loop
//----------------------------------------------------------------------
void OnTick()
{
  const string sym = _Symbol;

  // Spread/session filters
  if(!IsTradingAllowedNow()) return;
  if(!SpreadOK(sym)) return;

  if(!RefreshSymbolInfo(sym)) return;

  // One-position-per-symbol (any magic) for safety
  if(HasAnyPositionOnSymbol(sym))
  {
    // Manage our position if exists
    ulong t; long typ; double p, sl, tp, vol; 
    double atr; // need ATR for trailing
    if(EnsureIndicators(sym))
    {
      double atrbuf[]; ArraySetAsSeries(atrbuf,true);
      if(CopyBuffer(hATR,0,1,1,atrbuf)==1) atr = atrbuf[0]; else atr = 0.0;
    }
    if(GetOurPosition(sym, t, typ, p, sl, tp, vol))
      ManagePosition(sym, typ, atr);
    return;
  }

  // Generate signal on closed bar
  MqlRates rates[]; ArraySetAsSeries(rates,true);
  if(CopyRates(sym, InpTimeframe, 0, 3, rates) < 3) return;
  datetime lastClosed = rates[1].time;
  if(lastClosed == gLastClosedBarTime) return; // already processed this bar

  gLastClosedBarTime = lastClosed;

  double atr=0.0;
  int sig = Signal(sym, atr);
  if(sig==0) return;

  // Margin level quick check before heavier calcs
  double margin_level = AccountInfoDouble(ACCOUNT_MARGIN_LEVEL);
  if(InpMinMarginLevelPct>0.0 && margin_level>0.0 && margin_level < InpMinMarginLevelPct)
  {
    PrintFormat("Skip: current margin level %.1f%% < min %.1f%%", margin_level, InpMinMarginLevelPct);
    return;
  }

  // Compute order params & risk/margin validation
  double vol=0.0, sl=0.0, tp=0.0; string why="";
  if(!ComputeOrder(sym, sig, atr, vol, sl, tp, why))
  {
    Print("Order computation blocked: ", why);
    return;
  }

  // Final spread check again just before send
  if(!SpreadOK(sym)) { Print("Spread widened; aborting entry"); return; }

  // Place order
  if(!OpenPosition(sym, sig, vol, sl, tp, why))
  {
    Print("Entry failed: ", why);
    return;
  }

  PrintFormat("Opened %s %.2f lots with SL=%.5f TP=%.5f (ATR=%.5f)",
              (sig>0?"BUY":"SELL"), vol, sl, tp, atr);
}

//----------------------------------------------------------------------
// OnDeinit: cleanup
//----------------------------------------------------------------------
void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) { IndicatorRelease(hFastEMA); hFastEMA=INVALID_HANDLE; }
  if(hSlowEMA!=INVALID_HANDLE) { IndicatorRelease(hSlowEMA); hSlowEMA=INVALID_HANDLE; }
  if(hRSI!=INVALID_HANDLE)     { IndicatorRelease(hRSI);     hRSI=INVALID_HANDLE; }
  if(hATR!=INVALID_HANDLE)     { IndicatorRelease(hATR);     hATR=INVALID_HANDLE; }
}

//----------------------------------------------------------------------
// Error description helper
