string ErrorDescription(const int code)
{
  switch(code)
  {
    case 0: return "No error";
    case 1: return "No error returned, but the result is unknown";
    case 2: return "Common error";
    case 3: return "Invalid trade parameters";
    case 4: return "Trade server is busy";
    case 5: return "Old version of the client terminal";
    case 6: return "No connection with trade server";
    case 7: return "Not enough rights";
    case 8: return "Too frequent requests";
    case 64: return "Account disabled";
    case 65: return "Invalid account";
    case 133: return "Trading prohibited";
    case 134: return "Not enough money";
    case 135: return "Price changed";
    case 136: return "No quotes";
    case 137: return "Broker is busy";
    case 138: return "Requote";
    case 139: return "Order is blocked";
    case 141: return "Too many requests";
    case 145: return "Modification denied because order is too close to market";
    case 146: return "Trade context is busy";
    default: return "Error code: " + IntegerToString(code);
  }
}

//+------------------------------------------------------------------+
//|                                         EMA_RSI_ATR_Manager.mq5  |
//|       EMA Cross + RSI + ATR with robust risk & margin controls   |
//|       One-position-per-symbol, spread/session filters, trailing  |
//+------------------------------------------------------------------+
#property strict
#property version   "1.20"
#property description "EMA Cross + RSI + ATR strategy with complete trade management and robust margin/risk logic."

#include <Trade/Trade.mqh>

CTrade trade;

//========================
// Inputs: Strategy & Risk
//========================
input ENUM_TIMEFRAMES InpTimeframe      = PERIOD_M5;      // Signal timeframe
input int             InpFastEMA        = 21;             // Fast EMA period
input int             InpSlowEMA        = 55;             // Slow EMA period
input int             InpRSIPeriod      = 14;             // RSI period
input double          InpRSI_Buy        = 55.0;           // RSI threshold for buys
input double          InpRSI_Sell       = 45.0;           // RSI threshold for sells
input int             InpATRPeriod      = 14;             // ATR period
input double          InpATR_SL_Mult    = 1.5;            // SL = ATR * this multiplier
input double          InpATR_TrailMult  = 1.0;            // Trailing distance = ATR * this multiplier
input double          InpRR             = 2.0;            // Reward:Risk ratio
input double          InpATR_MinFilter  = 0.0;            // Minimum ATR filter (price units); set 0 to disable

//========================
// Inputs: Risk Management
//========================
input double          InpRiskPerTradePct          = 0.5;   // Percent of equity to risk per trade
input double          InpMaxFreeMarginUsagePct     = 10.0;  // Cap: single trade margin <= this % of free margin
input double          InpMinMarginLevelPct         = 500.0; // Do not open if margin level below this (%); ignored if <=0 or if account doesn't report level
input ulong           InpMagicNumber               = 987654321; // Magic number to tag positions

//========================
// Inputs: Execution & Filters
//========================
input int             InpSlippagePoints            = 20;    // Max deviation (points)
input int             InpMaxSpreadPoints           = 30;    // Max spread (points) allowed for entries
input string          InpSkipHoursUTC              = "21,22";// Skip trading on these UTC hours (comma-separated)
input bool            InpAllowTrailing             = true;  // Enable trailing SL
input double          InpBreakevenRR               = 1.0;   // Move SL to BE after reaching this RR (0 to disable)

//========================
// Internal state & handles
//========================
int     hFastEMA = INVALID_HANDLE;
int     hSlowEMA = INVALID_HANDLE;
int     hRSI     = INVALID_HANDLE;
int     hATR     = INVALID_HANDLE;

datetime gLastClosedBarTime = 0;

// Symbol parameters cache
double  gPoint      = 0.0;
int     gDigits     = 0;
double  gTickSize   = 0.0;
double  gTickValue  = 0.0;
double  gMinVolume  = 0.0;
double  gMaxVolume  = 0.0;
double  gVolStep    = 0.0;
int     gStopsLevelPoints = 0;
int     gFreezeLevelPoints = 0;

// Session skip hours (UTC)
bool    gSkipHour[24];

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
// Utility: Parse skip hours string to bool map
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
void ParseSkipHours(const string hours_csv)
{
  ArrayInitialize(gSkipHour,false);
  string trimmed = hours_csv;
  StringTrimLeft(trimmed);
  StringTrimRight(trimmed);
  if(trimmed=="") return;
  string parts[];
  int n = StringSplit(trimmed, ',', parts);
  for(int i=0;i<n;i++)
  {
    string p = parts[i];
    StringTrimLeft(p);
    StringTrimRight(p);
    if(p=="") continue;
    int h = (int)StringToInteger(p);
    if(h>=0 && h<24) gSkipHour[h]=true;
  }
}

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
// Utility: Refresh and cache symbol trading info
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
bool RefreshSymbolInfo(const string sym)
{
  if(!SymbolInfoDouble(sym, SYMBOL_POINT, gPoint)) return false;
  long ld=0;
  if(!SymbolInfoInteger(sym, SYMBOL_DIGITS, ld)) return false; gDigits=(int)ld;
  if(!SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_SIZE, gTickSize)) return false;
  if(!SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_VALUE, gTickValue)) return false;
  if(!SymbolInfoDouble(sym, SYMBOL_VOLUME_MIN, gMinVolume)) return false;
  if(!SymbolInfoDouble(sym, SYMBOL_VOLUME_MAX, gMaxVolume)) return false;
  if(!SymbolInfoDouble(sym, SYMBOL_VOLUME_STEP, gVolStep)) return false;
  long lv=0;
  if(SymbolInfoInteger(sym, SYMBOL_TRADE_STOPS_LEVEL, lv)) gStopsLevelPoints=(int)lv; else gStopsLevelPoints=0;
  if(SymbolInfoInteger(sym, SYMBOL_TRADE_FREEZE_LEVEL, lv)) gFreezeLevelPoints=(int)lv; else gFreezeLevelPoints=0;

  if(gPoint<=0 || gTickSize<=0 || gTickValue<=0 || gMinVolume<=0 || gVolStep<=0)
  {
    PrintFormat("Symbol info invalid: point=%.10f ticksize=%.10f tickvalue=%.10f minvol=%.2f volstep=%.2f",
                gPoint, gTickSize, gTickValue, gMinVolume, gVolStep);
    return false;
  }
  return true;
}

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
// Utility: Normalize lot volume to broker step
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
double NormalizeVolume(double vol)
{
  if(vol<=0) return 0.0;
  double steps = MathFloor(vol / gVolStep + 1e-9);
  double v = steps * gVolStep;
  if(v < gMinVolume) v = 0.0;
  if(v > gMaxVolume) v = gMaxVolume;
  // normalize to number of decimals implied by step
  int dec = 0;
  double s = gVolStep;
  while(dec<8 && MathRound(s*MathPow(10,dec)) - s*MathPow(10,dec) != 0.0) dec++;
  return NormalizeDouble(v, MathMax(2, dec));
}

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
// Utility: Normalize price to symbol digits
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
double NormalizePrice(double price)
{
  return NormalizeDouble(price, gDigits);
}

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
// Utility: One-position-per-symbol (any magic)
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
bool HasAnyPositionOnSymbol(const string sym)
{
  int total = PositionsTotal();
  for(int i=0;i<total;i++)
  {
    if(!PositionSelectByIndex(i)) continue;
    string psym = PositionGetString(POSITION_SYMBOL);
    if(psym==sym) return true;
  }
  return false;
}

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
// Utility: Get indicator values on closed bar
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
bool GetSignalData(const string sym, ENUM_TIMEFRAMES tf,
                   double &fastPrev, double &fastCurr,
                   double &slowPrev, double &slowCurr,
                   double &rsiPrev,  double &rsiCurr,
                   double &atrCurr)
{
  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
    return false;

  double fema[3], sema[3], r[3], a[3];
  if(CopyBuffer(hFastEMA, 0, 0, 3, fema) < 3) return false;
  if(CopyBuffer(hSlowEMA, 0, 0, 3, sema) < 3) return false;
  if(CopyBuffer(hRSI,     0, 0, 3, r)    < 3) return false;
  if(CopyBuffer(hATR,     0, 0, 3, a)    < 3) return false;

  // index 1 = last closed bar, index 2 = previous closed bar
  fastCurr = fema[1]; fastPrev = fema[2];
  slowCurr = sema[1]; slowPrev = sema[2];
  rsiCurr  = r[1];    rsiPrev  = r[2];
  atrCurr  = a[1];
  return true;
}

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
// Utility: Time/Session and spread filters
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
bool SessionAndSpreadOK(const string sym)
{
  // session hour (UTC from TimeGMT)
  datetime gmt = TimeGMT();
  MqlDateTime dt; TimeToStruct(gmt, dt);
  if(dt.hour>=0 && dt.hour<24 && gSkipHour[dt.hour])
  {
    PrintFormat("Skip hour (UTC %d) per configuration.", dt.hour);
    return false;
  }

  // spread filter
  double ask=0,bid=0;
  if(!SymbolInfoDouble(sym, SYMBOL_ASK, ask) || !SymbolInfoDouble(sym, SYMBOL_BID, bid))
  {
    Print("Failed to read prices for spread check");
    return false;
  }
  double spreadPoints = (ask - bid) / gPoint;
  if(InpMaxSpreadPoints>0 && spreadPoints > InpMaxSpreadPoints)
  {
    PrintFormat("Spread too high: %.1f > max %d points", spreadPoints, InpMaxSpreadPoints);
    return false;
  }
  return true;
}

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
// Risk sizing: compute volume from equity risk and SL distance
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
bool ComputeVolumeByRisk(const string sym, ENUM_ORDER_TYPE type, double sl_price, double entry, double &volumeOut)
{
  volumeOut = 0.0;
  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  if(equity<=0) { Print("Equity unavailable"); return false; }

  double riskMoney = equity * (InpRiskPerTradePct/100.0);
  if(riskMoney <= 0) { Print("Risk per trade is zero"); return false; }

  double stopDistance = MathAbs(entry - sl_price);
  if(stopDistance <= 0) { Print("Invalid SL distance"); return false; }

  // pip value approximation using tick value/size
  double ticks = stopDistance / gTickSize;
  if(ticks <= 0) { Print("Computed ticks <= 0"); return false; }

  // value per lot for the stop distance
  double valuePerLot = (ticks * gTickValue);
  if(valuePerLot <= 0) { Print("Invalid valuePerLot"); return false; }

  double vol = riskMoney / valuePerLot;
  vol = NormalizeVolume(vol);
  if(vol <= 0) { Print("Computed volume below min volume"); return false; }

  // Margin cap check using OrderCalcMargin
  double margin=0.0;
  if(!OrderCalcMargin(type, sym, vol, entry, margin))
  {
    PrintFormat("OrderCalcMargin failed, err=%d", GetLastError());
    return false;
  }

  double freeMargin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(freeMargin<=0) { Print("Free margin unavailable"); return false; }

  double cap = freeMargin * (InpMaxFreeMarginUsagePct/100.0);
  if(InpMaxFreeMarginUsagePct>0 && margin > cap)
  {
    // scale volume down to meet margin cap
    double scale = cap / margin;
    double vol2 = NormalizeVolume(vol * scale);
    if(vol2 <= 0) { Print("Volume reduced by margin cap below minimum"); return false; }
    vol = vol2;
    // recompute margin for logging (optional)
    if(!OrderCalcMargin(type, sym, vol, entry, margin))
    {
      PrintFormat("OrderCalcMargin retry failed, err=%d", GetLastError());
      return false;
    }
  }

  // Check minimum margin level if provided
  double marginLevel = AccountInfoDouble(ACCOUNT_MARGIN_LEVEL);
  if(InpMinMarginLevelPct>0 && marginLevel>0 && marginLevel < InpMinMarginLevelPct)
  {
    PrintFormat("Margin level %.2f%% below threshold %.2f%%, block entry", marginLevel, InpMinMarginLevelPct);
    return false;
  }

  volumeOut = vol;
  return true;
}

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
// Build SL/TP based on ATR and RR
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
void BuildSLTP(const string sym, ENUM_ORDER_TYPE type, double entry, double atr,
               double &slOut, double &tpOut)
{
  double riskDist = atr * InpATR_SL_Mult;
  if(type==ORDER_TYPE_BUY)
  {
    slOut = NormalizePrice(entry - riskDist);
    tpOut = NormalizePrice(entry + riskDist * InpRR);
  }
  else
  {
    slOut = NormalizePrice(entry + riskDist);
    tpOut = NormalizePrice(entry - riskDist * InpRR);
  }

  // Respect stops/freeze levels
  int minDistPts = MathMax(gStopsLevelPoints, gFreezeLevelPoints);
  double minDist = minDistPts * gPoint;
  if(type==ORDER_TYPE_BUY)
  {
    if((entry - slOut) < minDist) slOut = NormalizePrice(entry - minDist);
    if((tpOut - entry) < minDist) tpOut = NormalizePrice(entry + minDist);
  }
  else
  {
    if((slOut - entry) < minDist) slOut = NormalizePrice(entry + minDist);
    if((entry - tpOut) < minDist) tpOut = NormalizePrice(entry - minDist);
  }
}

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
// Entry logic: EMA cross + RSI filter + ATR volatility filter
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
bool GetEntrySignal(const string sym, double &atrOut, ENUM_ORDER_TYPE &typeOut)
{
  double fPrev,fCurr,sPrev,sCurr,rPrev,rCurr,atr;
  if(!GetSignalData(sym, InpTimeframe, fPrev,fCurr,sPrev,sCurr,rPrev,rCurr,atr)) return false;

  if(InpATR_MinFilter>0 && atr < InpATR_MinFilter) return false;

  // Cross on last closed bar with RSI confirmation on same bar
  bool bullCross = (fPrev < sPrev) && (fCurr > sCurr) && (rCurr >= InpRSI_Buy);
  bool bearCross = (fPrev > sPrev) && (fCurr < sCurr) && (rCurr <= InpRSI_Sell);

  if(bullCross) { typeOut = ORDER_TYPE_BUY; atrOut = atr; return true; }
  if(bearCross) { typeOut = ORDER_TYPE_SELL; atrOut = atr; return true; }
  return false;
}

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
// Trailing stop and breakeven management
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
void ManagePosition(const string sym)
{
  if(!PositionSelect(sym)) return;
  long ptype   = PositionGetInteger(POSITION_TYPE);
  double vol   = PositionGetDouble(POSITION_VOLUME);
  double open  = PositionGetDouble(POSITION_PRICE_OPEN);
  double sl    = PositionGetDouble(POSITION_SL);
  double tp    = PositionGetDouble(POSITION_TP);
  double price = (ptype==POSITION_TYPE_BUY) ? SymbolInfoDouble(sym, SYMBOL_BID) : SymbolInfoDouble(sym, SYMBOL_ASK);

  // Read ATR for trailing distance
  double a[2];
  if(CopyBuffer(hATR, 0, 0, 2, a) < 2) return;
  double atr = a[0];
  double trailDist = atr * InpATR_TrailMult;

  // Breakeven logic
  if(InpBreakevenRR>0 && sl>0)
  {
    double riskPerUnit = MathAbs(open - sl);
    double beTrigger   = open + ((ptype==POSITION_TYPE_BUY)? 1 : -1) * (riskPerUnit * InpBreakevenRR);
    if((ptype==POSITION_TYPE_BUY && price >= beTrigger) || (ptype==POSITION_TYPE_SELL && price <= beTrigger))
    {
      double newSL = (ptype==POSITION_TYPE_BUY)? open : open;
      newSL = NormalizePrice(newSL);
      if((ptype==POSITION_TYPE_BUY && (newSL>sl)) || (ptype==POSITION_TYPE_SELL && (newSL<sl)))
      {
        if(!trade.PositionModify(sym, newSL, tp))
          PrintFormat("Breakeven modify failed %d", GetLastError());
      }
    }
  }

  if(!InpAllowTrailing) return;

  double desiredSL;
  if(ptype==POSITION_TYPE_BUY)
  {
    desiredSL = NormalizePrice(price - trailDist);
    if(sl==0 || desiredSL > sl)
    {
      if(!trade.PositionModify(sym, desiredSL, tp))
        PrintFormat("Trail modify failed %d", GetLastError());
    }
  }
  else if(ptype==POSITION_TYPE_SELL)
  {
    desiredSL = NormalizePrice(price + trailDist);
    if(sl==0 || desiredSL < sl)
    {
      if(!trade.PositionModify(sym, desiredSL, tp))
        PrintFormat("Trail modify failed %d", GetLastError());
    }
  }
}

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
// Place order with full validation and error handling
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
bool PlaceEntry(const string sym, ENUM_ORDER_TYPE type, double atr)
{
  MqlTick tick; if(!SymbolInfoTick(sym, tick)) { Print("No tick"); return false; }
  double entry = (type==ORDER_TYPE_BUY)? tick.ask : tick.bid;

  double sl=0,tp=0; BuildSLTP(sym, type, entry, atr, sl, tp);

  // volume sizing with risk and margin caps
  double volume=0.0;
  if(!ComputeVolumeByRisk(sym, type, sl, entry, volume)) return false;

  // final pre-trade free margin/level re-check with computed volume
  double margin=0.0;
  if(!OrderCalcMargin(type, sym, volume, entry, margin))
  { PrintFormat("OrderCalcMargin final failed %d", GetLastError()); return false; }

  double freeMargin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(freeMargin <= margin)
  { PrintFormat("Insufficient free margin: need %.2f, have %.2f", margin, freeMargin); return false; }

  double marginLevel = AccountInfoDouble(ACCOUNT_MARGIN_LEVEL);
  if(InpMinMarginLevelPct>0 && marginLevel>0 && marginLevel < InpMinMarginLevelPct)
  { PrintFormat("Margin level %.2f%% below threshold %.2f%%", marginLevel, InpMinMarginLevelPct); return false; }

  trade.SetExpertMagicNumber(InpMagicNumber);
  trade.SetDeviationInPoints(InpSlippagePoints);

  bool ok=false;
  if(type==ORDER_TYPE_BUY)
    ok = trade.Buy(volume, sym, entry, sl, tp, "EMA_RSI_ATR Buy");
  else
    ok = trade.Sell(volume, sym, entry, sl, tp, "EMA_RSI_ATR Sell");

  if(!ok)
  {
    int err = GetLastError();
    PrintFormat("Order send failed: err=%d vol=%.2f entry=%.5f sl=%.5f tp=%.5f", err, volume, entry, sl, tp);
    return false;
  }
  return true;
}

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
// OnInit: create indicators and cache symbol data
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
int OnInit()
{
  const string sym = _Symbol;
  if(!RefreshSymbolInfo(sym)) { Print("RefreshSymbolInfo failed"); return INIT_FAILED; }

  ParseSkipHours(InpSkipHoursUTC);

  hFastEMA = iMA(sym, InpTimeframe, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
  hSlowEMA = iMA(sym, InpTimeframe, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
  hRSI     = iRSI(sym, InpTimeframe, InpRSIPeriod, PRICE_CLOSE);
  hATR     = iATR(sym, InpTimeframe, InpATRPeriod);

  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
  {
    Print("Indicator handle creation failed");
    return INIT_FAILED;
  }

  // Prime last closed bar time
  datetime times[2];
  if(CopyTime(sym, InpTimeframe, 0, 2, times) >= 2)
    gLastClosedBarTime = times[1];

  return INIT_SUCCEEDED;
}

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
// OnDeinit: release resources
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);
}

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
// OnTick: enforce filters, one-position rule, entries and management
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
void OnTick()
{
  const string sym = _Symbol;
  if(!RefreshSymbolInfo(sym)) return;
  if(!SessionAndSpreadOK(sym)) return;

  // One-position-per-symbol (strict)
  if(HasAnyPositionOnSymbol(sym))
  {
    // manage trailing for existing
    ManagePosition(sym);
    return;
  }

  // New bar check to avoid intra-bar multiple entries
  datetime times[2];
  if(CopyTime(sym, InpTimeframe, 0, 2, times) < 2) return;
  datetime lastClosed = times[1];
  if(lastClosed == 0) return;
  if(lastClosed == gLastClosedBarTime)
    return; // wait until a new bar closes

  gLastClosedBarTime = lastClosed;

  // Generate entry signal
  ENUM_ORDER_TYPE type;
  double atr;
  if(!GetEntrySignal(sym, atr, type)) return;

  // Place entry with full risk/margin controls
  PlaceEntry(sym, type, atr);
}

