//------------------------------------------------------------------
// Helpers
//------------------------------------------------------------------
void LogLastError(const string context)
{
  int err = GetLastError();
  PrintFormat("%s | Error %d: %s", context, err, ErrorDescription(err));
}

void ParseSkipHours(const string hours_csv)
{
  ArrayInitialize(gSkipHour,false);
  string trimmed = StringTrim(hours_csv);
  if(trimmed=="") return;
  string parts[];
  int n = StringSplit(trimmed, ',', parts);
  for(int i=0;i<n;i++)
  {
    string p = StringTrim(parts[i]);
    if(p=="") continue;
    int h = (int)StringToInteger(p);
    if(h>=0 && h<24) gSkipHour[h]=true;
  }
}

bool RefreshSymbolInfo(const string sym)
{
  gSymbol = sym;
  if(!SymbolSelect(gSymbol, true))
  {
    LogLastError("SymbolSelect failed");
    return false;
  }

  gPoint  = SymbolInfoDouble(gSymbol, SYMBOL_POINT);
  gDigits = (int)SymbolInfoInteger(gSymbol, SYMBOL_DIGITS);
  gTickSize = SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_SIZE);
  gTickValue= SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_VALUE);
  gMinVolume= SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MIN);
  gMaxVolume= SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MAX);
  gVolStep  = SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_STEP);
  gStopsLevelPoints  = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_STOPS_LEVEL);
  gFreezeLevelPoints = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_FREEZE_LEVEL);

  long trade_mode = SymbolInfoInteger(gSymbol, SYMBOL_TRADE_MODE);
  if(trade_mode == SYMBOL_TRADE_MODE_DISABLED || trade_mode == SYMBOL_TRADE_MODE_CLOSEONLY)
  {
    PrintFormat("Trading not allowed for symbol %s (mode=%d)", gSymbol, trade_mode);
    return false;
  }
  return true;
}

bool GetIndicatorValues(double &emaFast, double &emaSlow, double &rsi, double &atr)
{
  emaFast = emaSlow = rsi = atr = 0.0;
  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
    return false;

  if(!RefreshRates())
    return false;

  double bufFast[], bufSlow[], bufRSI[], bufATR[];
  if(CopyBuffer(hFastEMA, 0, 0, 3, bufFast) < 3) return false;
  if(CopyBuffer(hSlowEMA, 0, 0, 3, bufSlow) < 3) return false;
  if(CopyBuffer(hRSI,     0, 0, 3, bufRSI ) < 3) return false;
  if(CopyBuffer(hATR,     0, 0, 3, bufATR ) < 3) return false;

  // Use closed bar (index 1)
  emaFast = bufFast[1];
  emaSlow = bufSlow[1];
  rsi     = bufRSI[1];
  atr     = bufATR[1];
  return (emaFast>0 && emaSlow>0 && rsi>0 && atr>=0);
}

bool IsNewBar()
{
  MqlRates rates[];
  if(CopyRates(gSymbol, InpTimeframe, 0, 2, rates) != 2)
    return false;
  datetime bar_time = rates[0].time; // current forming bar
  if(bar_time != gLastSignalBarTime)
  {
    gLastSignalBarTime = bar_time;
    return true;
  }
  return false;
}

bool WithinSession()
{
  datetime now = TimeCurrent();
  MqlDateTime dt; TimeToStruct(now, dt);
  int utc_hour = dt.hour; // server time assumed UTC or adjust if needed
  if(utc_hour < 0 || utc_hour > 23) return true;
  return !gSkipHour[utc_hour];
}

bool SpreadOK()
{
  double spread_points = (SymbolInfoDouble(gSymbol, SYMBOL_ASK) - SymbolInfoDouble(gSymbol, SYMBOL_BID)) / gPoint;
  return (spread_points <= InpMaxSpreadPoints);
}

int CountOpenPositionsForSymbol()
{
  int total = PositionsTotal();
  int count = 0;
  for(int i=0;i<total;i++)
  {
    ulong ticket = PositionGetTicket(i);
    if(ticket==0) continue;
    if(!PositionSelectByTicket(ticket)) continue;
    if((string)PositionGetString(POSITION_SYMBOL) == gSymbol)
      count++;
  }
  return count;
}

// Round volume to broker step and bounds
double NormalizeVolume(double vol)
{
  if(gVolStep>0) vol = MathFloor(vol / gVolStep) * gVolStep;
  if(vol < gMinVolume) vol = 0.0;
  if(gMaxVolume>0 && vol > gMaxVolume) vol = gMaxVolume;
  return NormalizeDouble(vol, (gVolStep>=0.01 ? 2 : 3));
}

// Compute stop loss price based on ATR multiplier and direction
bool ComputeSLTP(int dir, double atr, double rr, double &sl, double &tp)
{
  double ask = SymbolInfoDouble(gSymbol, SYMBOL_ASK);
  double bid = SymbolInfoDouble(gSymbol, SYMBOL_BID);
  if(ask<=0 || bid<=0) return false;

  double price = (dir>0 ? ask : bid);
  double sl_dist = atr * InpATR_SL_Mult;
  if(sl_dist <= 0.0) return false;

  // Respect stops level
  double min_stop = (gStopsLevelPoints>0 ? gStopsLevelPoints * gPoint : 0.0);
  if(sl_dist < min_stop) sl_dist = min_stop;

  if(dir>0)
  {
    sl = price - sl_dist;
    tp = price + sl_dist * rr;
  }
  else
  {
    sl = price + sl_dist;
    tp = price - sl_dist * rr;
  }

  // Avoid freeze level proximity
  double freeze = (gFreezeLevelPoints>0 ? gFreezeLevelPoints * gPoint : 0.0);
  if(dir>0 && (ask - sl) < freeze) sl = ask - freeze;
  if(dir<0 && (sl - bid) < freeze) sl = bid + freeze;

  sl = NormalizeDouble(sl, gDigits);
  tp = NormalizeDouble(tp, gDigits);
  return true;
}

// Calculate position size from equity risk and SL distance via OrderCalcMargin
bool CalculateVolumeByRisk(int dir, double sl, double &volume)
{
  double price = (dir>0 ? SymbolInfoDouble(gSymbol, SYMBOL_ASK) : SymbolInfoDouble(gSymbol, SYMBOL_BID));
  if(price<=0) return false;

  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  double free_margin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(equity<=0 || free_margin<0) return false;

  // Risk in account currency
  double risk_amount = equity * (InpRiskPerTradePct/100.0);
  if(risk_amount <= 0) { volume = 0.0; return false; }

  double sl_dist_price = MathAbs(price - sl);
  if(sl_dist_price <= 0) { volume = 0.0; return false; }

  // Risk per 1 lot approximated using tick value
  // pips_value for 1 lot over sl distance
  double ticks = sl_dist_price / gTickSize;
  if(gTickSize<=0 || gTickValue<=0) return false;
  double risk_per_lot = ticks * gTickValue;
  if(risk_per_lot <= 0) return false;

  double raw_volume = risk_amount / risk_per_lot;
  raw_volume = MathMax(raw_volume, 0.0);

  // Now enforce margin cap using OrderCalcMargin iteratively
  double vol = NormalizeVolume(raw_volume);
  if(vol <= 0.0) { volume = 0.0; return false; }

  const ENUM_ORDER_TYPE order_type = (dir>0 ? ORDER_TYPE_BUY : ORDER_TYPE_SELL);
  double margin_needed = 0.0;
  if(!OrderCalcMargin(order_type, gSymbol, vol, price, margin_needed))
  {
    LogLastError("OrderCalcMargin failed");
    return false;
  }

  // Cap by free margin usage
  double cap = free_margin * (InpMaxFreeMarginUsagePct/100.0);
  if(cap > 0 && margin_needed > cap)
  {
    // Scale down
    double scale = cap / margin_needed;
    vol = NormalizeVolume(vol * scale);
    if(vol <= 0.0) { volume = 0.0; return false; }
    if(!OrderCalcMargin(order_type, gSymbol, vol, price, margin_needed))
    {
      LogLastError("OrderCalcMargin(recalc) failed");
      return false;
    }
  }

  // Check margin level constraint (simulate post-trade)
  double margin_current = AccountInfoDouble(ACCOUNT_MARGIN);
  double balance_equity = equity; // equity after open roughly equity (ignoring commission/spread)
  double margin_after = margin_current + margin_needed;
  if(margin_after > 0 && InpMinMarginLevelPct > 0.0)
  {
    double level_after = (balance_equity / margin_after) * 100.0;
    if(level_after < InpMinMarginLevelPct)
    {
      // Try reduce volume proportionally
      double target_margin_after = balance_equity / (InpMinMarginLevelPct/100.0);
      double allowable_increment = MathMax(0.0, target_margin_after - margin_current);
      if(allowable_increment <= 0.0)
      {
        volume = 0.0;
        return false;
      }
      double scale2 = allowable_increment / margin_needed;
      vol = NormalizeVolume(vol * MathMin(1.0, scale2));
      if(vol <= 0.0) { volume = 0.0; return false; }
      if(!OrderCalcMargin(order_type, gSymbol, vol, price, margin_needed))
      {
        LogLastError("OrderCalcMargin(recalc2) failed");
        return false;
      }
      margin_after = margin_current + margin_needed;
      double level_after2 = (balance_equity / margin_after) * 100.0;
      if(level_after2 < InpMinMarginLevelPct)
      {
        volume = 0.0;
        return false;
      }
    }
  }

  volume = vol;
  return (volume > 0.0);
}

void SetupRequest(ENUM_ORDER_TYPE type, double volume, double price, double sl, double tp, MqlTradeRequest &req)
{
  ZeroMemory(req);
  req.action   = TRADE_ACTION_DEAL;
  req.symbol   = gSymbol;
  req.type     = type;
  req.volume   = volume;
  req.price    = price;
  req.sl       = sl;
  req.tp       = tp;
  req.deviation= InpSlippagePoints;
  req.magic    = InpMagicNumber;
  req.type_filling = ORDER_FILLING_FOK;
  req.type_time    = ORDER_TIME_GTC;
}

bool SendOrder(ENUM_ORDER_TYPE type, double volume, double sl, double tp)
{
  double price = (type==ORDER_TYPE_BUY ? SymbolInfoDouble(gSymbol, SYMBOL_ASK) : SymbolInfoDouble(gSymbol, SYMBOL_BID));
  MqlTradeRequest req; MqlTradeResult res;
  SetupRequest(type, volume, price, sl, tp, req);
  if(!OrderSend(req, res))
  {
    LogLastError("OrderSend failed");
    return false;
  }
  if(res.retcode != TRADE_RETCODE_DONE && res.retcode != TRADE_RETCODE_PLACED)
  {
    PrintFormat("Order rejected: retcode=%d comment=%s", res.retcode, res.comment);
    return false;
  }
  return true;
}

void TrailPosition()
{
  if(!InpAllowTrailing) return;
  if(!PositionSelect(gSymbol)) return;

  ENUM_POSITION_TYPE ptype = (ENUM_POSITION_TYPE)PositionGetInteger(POSITION_TYPE);
  double pos_price = PositionGetDouble(POSITION_PRICE_OPEN);
  double sl        = PositionGetDouble(POSITION_SL);
  double volume    = PositionGetDouble(POSITION_VOLUME);

  double ask = SymbolInfoDouble(gSymbol, SYMBOL_ASK);
  double bid = SymbolInfoDouble(gSymbol, SYMBOL_BID);

  double atr=0, e1, e2, r;
  if(!GetIndicatorValues(e1,e2,r,atr)) return;

  double trail_dist = atr * InpATR_TrailMult;
  double min_stop = (gStopsLevelPoints>0 ? gStopsLevelPoints * gPoint : 0.0);
  if(trail_dist < min_stop) trail_dist = min_stop;

  double new_sl = sl;
  if(ptype == POSITION_TYPE_BUY)
  {
    double be_price = pos_price; // breakeven baseline
    if(InpBreakevenRR > 0)
    {
      double sl_dist = MathAbs(pos_price - sl);
      if(sl_dist>0 && (bid - pos_price) >= sl_dist * InpBreakevenRR)
        be_price = pos_price; // move to BE allowed
    }
    double candidate = bid - trail_dist;
    if(candidate > be_price) new_sl = MathMax(sl, NormalizeDouble(candidate, gDigits));
  }
  else if(ptype == POSITION_TYPE_SELL)
  {
    double be_price = pos_price;
    if(InpBreakevenRR > 0)
    {
      double sl_dist = MathAbs(pos_price - sl);
      if(sl_dist>0 && (pos_price - ask) >= sl_dist * InpBreakevenRR)
        be_price = pos_price;
    }
    double candidate = ask + trail_dist;
    if(candidate < be_price) new_sl = MathMin(sl, NormalizeDouble(candidate, gDigits));
  }

  if(new_sl != sl)
  {
    MqlTradeRequest req; MqlTradeResult res;
    ZeroMemory(req); ZeroMemory(res);
    req.action = TRADE_ACTION_SLTP;
    req.symbol = gSymbol;
    req.sl     = new_sl;
    req.tp     = PositionGetDouble(POSITION_TP);
    req.magic  = InpMagicNumber;
    if(!OrderSend(req,res)) LogLastError("Modify SL failed");
  }
}

bool GenerateSignal(int &dir)
{
  dir = 0;
  double emaF, emaS, rsi, atr;
  if(!GetIndicatorValues(emaF, emaS, rsi, atr)) return false;
  if(InpATR_MinFilter>0 && atr < InpATR_MinFilter) return false;

  // EMA cross confirmation using last two closed bars
  double emaF_now, emaS_now, rsi_now, atr_now;
  double bufFast[3], bufSlow[3], bufRSI[3];
  if(CopyBuffer(hFastEMA,0,0,3,bufFast)<3) return false;
  if(CopyBuffer(hSlowEMA,0,0,3,bufSlow)<3) return false;
  if(CopyBuffer(hRSI,0,0,3,bufRSI)<3) return false;
  emaF_now = bufFast[1]; emaS_now = bufSlow[1];
  double emaF_prev = bufFast[2];
  double emaS_prev = bufSlow[2];
  rsi_now  = bufRSI[1];

  bool bull_cross = (emaF_prev <= emaS_prev) && (emaF_now > emaS_now) && (rsi_now >= InpRSI_Buy);
  bool bear_cross = (emaF_prev >= emaS_prev) && (emaF_now < emaS_now) && (rsi_now <= InpRSI_Sell);

  if(bull_cross) dir = +1;
  else if(bear_cross) dir = -1;
  else dir = 0;

  return true;
}

//+------------------------------------------------------------------+
//| Expert initialization function                                   |
//+------------------------------------------------------------------+
int OnInit()
{
  if(!RefreshSymbolInfo(_Symbol))
  {
    Print("Initialization failed: symbol info");
    return(INIT_FAILED);
  }

  ParseSkipHours(InpSkipHoursUTC);

  // Create indicators
  hFastEMA = iMA(gSymbol, InpTimeframe, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
  hSlowEMA = iMA(gSymbol, InpTimeframe, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
  hRSI     = iRSI(gSymbol, InpTimeframe, InpRSIPeriod, PRICE_CLOSE);
  hATR     = iATR(gSymbol, InpTimeframe, InpATRPeriod);

  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
  {
    Print("Initialization failed: indicator handles");
    return(INIT_FAILED);
  }

  // Set trade properties
  trade.SetExpertMagicNumber((int)InpMagicNumber);
  trade.SetTypeFilling(ORDER_FILLING_FOK);
  trade.SetTypeTime(ORDER_TIME_GTC);

  return(INIT_SUCCEEDED);
}

//+------------------------------------------------------------------+
//| Expert tick function                                             |
//+------------------------------------------------------------------+
void OnTick()
{
  if(!RefreshSymbolInfo(_Symbol)) return;

  // Only evaluate once per new bar for entries
  bool newbar = IsNewBar();

  // Trailing management on every tick
  TrailPosition();

  if(!newbar) return;

  // Filters
  if(!WithinSession()) return;
  if(!SpreadOK()) return;

  // Enforce one-position-per-symbol
  if(CountOpenPositionsForSymbol() > 0) return;

  int dir = 0;
  if(!GenerateSignal(dir)) return;
  if(dir==0) return;

  double emaF, emaS, rsi, atr;
  if(!GetIndicatorValues(emaF, emaS, rsi, atr)) return;

  double sl=0.0, tp=0.0;
  if(!ComputeSLTP(dir, atr, InpRR, sl, tp)) return;

  // Volume by risk and margin controls
  double volume=0.0;
  if(!CalculateVolumeByRisk(dir, sl, volume))
  {
    Print("Sizing failed: constraints or calc error");
    return;
  }

  if(volume <= 0.0) return;

  // Safety: final free margin and margin level check just before send
  double price = (dir>0 ? SymbolInfoDouble(gSymbol, SYMBOL_ASK) : SymbolInfoDouble(gSymbol, SYMBOL_BID));
  double margin_needed=0.0;
  ENUM_ORDER_TYPE otype = (dir>0 ? ORDER_TYPE_BUY : ORDER_TYPE_SELL);
  if(!OrderCalcMargin(otype, gSymbol, volume, price, margin_needed))
  {
    LogLastError("OrderCalcMargin final check failed");
    return;
  }

  double free_margin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(InpMaxFreeMarginUsagePct>0)
  {
    double cap = free_margin * (InpMaxFreeMarginUsagePct/100.0);
    if(margin_needed > cap)
    {
      Print("Aborted: margin_needed exceeds cap");
      return;
    }
  }

  if(InpMinMarginLevelPct > 0.0)
  {
    double equity = AccountInfoDouble(ACCOUNT_EQUITY);
    double margin_after = AccountInfoDouble(ACCOUNT_MARGIN) + margin_needed;
    if(margin_after>0)
    {
      double level_after = (equity / margin_after) * 100.0;
      if(level_after < InpMinMarginLevelPct)
      {
        Print("Aborted: margin level would be below threshold");
        return;
      }
    }
  }

  // Place order
  if(dir>0)
  {
    if(!SendOrder(ORDER_TYPE_BUY, volume, sl, tp)) return;
  }
  else
  {
    if(!SendOrder(ORDER_TYPE_SELL, volume, sl, tp)) return;
  }
}

//+------------------------------------------------------------------+
//| Expert deinitialization function                                 |
//+------------------------------------------------------------------+
void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);
}

