// Symbol parameters cache
string  gSymbol;
double  gPoint      = 0.0;
int     gDigits     = 0;
double  gTickSize   = 0.0;
double  gTickValue  = 0.0;
double  gMinVolume  = 0.0;
double  gMaxVolume  = 0.0;
double  gVolStep    = 0.0;
int     gStopsLevelPoints = 0;
int     gFreezeLevelPoints = 0;

// Session skip hours (UTC) map
bool    gSkipHour[24];

//==================================================================
// Helpers
//==================================================================
void LogLastError(const string context)
{
  int err = GetLastError();
  ResetLastError();
  PrintFormat("%s | Error %d: %s", context, err, ErrorDescription(err));
}

void ParseSkipHours(const string hours_csv)
{
  ArrayInitialize(gSkipHour,false);
  string trimmed = StringTrim(hours_csv);
  if(trimmed=="") return;
  string parts[];
  int n = StringSplit(trimmed, ',', parts);
  for(int i=0;i<n;i++)
  {
    string p = StringTrim(parts[i]);
    if(p=="") continue;
    int h = (int)StringToInteger(p);
    if(h>=0 && h<24) gSkipHour[h]=true;
  }
}

bool RefreshSymbolInfo(const string sym)
{
  gSymbol = sym;
  if(!SymbolSelect(gSymbol, true))
  {
    LogLastError("SymbolSelect failed");
    return false;
  }

  gPoint  = SymbolInfoDouble(gSymbol, SYMBOL_POINT);
  gDigits = (int)SymbolInfoInteger(gSymbol, SYMBOL_DIGITS);
  gTickSize = SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_SIZE);
  gTickValue= SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_VALUE);
  gMinVolume= SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MIN);
  gMaxVolume= SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MAX);
  gVolStep  = SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_STEP);
  gStopsLevelPoints  = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_STOPS_LEVEL);
  gFreezeLevelPoints = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_FREEZE_LEVEL);

  long trade_mode = SymbolInfoInteger(gSymbol, SYMBOL_TRADE_MODE);
  if(trade_mode == SYMBOL_TRADE_MODE_DISABLED || trade_mode == SYMBOL_TRADE_MODE_CLOSEONLY)
  {
    PrintFormat("Trading not allowed for symbol %s (mode=%d)", gSymbol, trade_mode);
    return false;
  }

  if(gPoint<=0.0 || gTickValue<=0.0 || gMinVolume<=0.0 || gVolStep<=0.0)
  {
    Print("Invalid symbol parameters");
    return false;
  }

  return true;
}

bool GetLatestValues(const int handle, double &out0, const int shift=0)
{
  out0 = 0.0;
  if(handle==INVALID_HANDLE) return false;
  double buf[];
  if(CopyBuffer(handle,0,shift,2,buf)<=0) return false;
  out0 = buf[0];
  return true;
}

int CountOpenPositionsForSymbol(const string sym, const ulong magic)
{
  int count=0;
  for(int i=0;i<PositionsTotal();i++)
  {
    ulong ticket = PositionGetTicket(i);
    if(ticket==0) continue;
    if(!PositionSelectByTicket(ticket)) continue;
    if(PositionGetString(POSITION_SYMBOL)==sym && PositionGetInteger(POSITION_MAGIC)==(long)magic)
      count++;
  }
  return count;
}

bool IsSessionBlocked()
{
  datetime now_utc = TimeCurrent();
  MqlDateTime t; TimeToStruct(now_utc, t);
  return gSkipHour[t.hour];
}

bool CheckSpreadOk(const string sym, const int max_points)
{
  double ask = 0, bid = 0;
  if(!SymbolInfoDouble(sym, SYMBOL_ASK, ask) || !SymbolInfoDouble(sym, SYMBOL_BID, bid))
    return false;
  int spread_points = (int)MathRound((ask - bid) / gPoint);
  return spread_points <= max_points;
}

// Calculate position size by equity risk using OrderCalcMargin to respect margin
bool CalcVolumeByRisk(const bool is_buy, const double entry_price, const double sl_price,
                      const double risk_pct, const double max_free_margin_pct,
                      double &out_volume, double &out_est_margin)
{
  out_volume = 0.0; out_est_margin = 0.0;
  if(sl_price<=0.0 || entry_price<=0.0 || entry_price==sl_price) return false;

  double equity, balance, free_margin, margin, margin_level;
  AccountInfoDouble(ACCOUNT_EQUITY,  equity);
  AccountInfoDouble(ACCOUNT_BALANCE, balance);
  AccountInfoDouble(ACCOUNT_FREEMARGIN, free_margin);
  AccountInfoDouble(ACCOUNT_MARGIN, margin);
  AccountInfoDouble(ACCOUNT_MARGIN_LEVEL, margin_level);

  // Risk in account currency
  double risk_money = equity * (risk_pct/100.0);
  if(risk_money<=0.0) return false;

  // Tick value per point (approx)
  double pt_value = gTickValue * (gPoint / gTickSize);
  double sl_points = MathAbs(entry_price - sl_price) / gPoint;
  if(sl_points<1.0) sl_points = 1.0;

  // Raw volume from risk/SL
  double vol_from_risk = risk_money / (sl_points * pt_value);

  // Clamp to symbol limits
  double vol = MathMax(gMinVolume, MathMin(vol_from_risk, gMaxVolume));
  // Normalize to step
  vol = MathFloor(vol / gVolStep) * gVolStep;
  if(vol < gMinVolume) vol = gMinVolume;

  if(vol<=0.0) return false;

  // Margin per 1.0 lot using OrderCalcMargin; scale by vol later to robustly cap
  double per_lot_margin = 0.0;
  ENUM_ORDER_TYPE ot = is_buy ? ORDER_TYPE_BUY : ORDER_TYPE_SELL;
  if(!OrderCalcMargin(ot, gSymbol, 1.0, entry_price, per_lot_margin))
  {
    LogLastError("OrderCalcMargin per lot failed");
    return false;
  }

  double est_margin = per_lot_margin * vol;

  // Cap by free margin usage
  double max_allowed_margin = free_margin * (max_free_margin_pct/100.0);
  if(max_allowed_margin>0.0 && est_margin > max_allowed_margin)
  {
    // Reduce vol to fit cap
    double capped_vol = max_allowed_margin / MathMax(per_lot_margin, 1e-8);
    capped_vol = MathFloor(capped_vol / gVolStep) * gVolStep;
    capped_vol = MathMax(0.0, MathMin(capped_vol, gMaxVolume));
    if(capped_vol < gMinVolume)
      return false; // Cannot fit within margin cap
    vol = capped_vol;
    est_margin = per_lot_margin * vol;
  }

  // Projected margin level after opening (approx)
  double proj_used_margin = margin + est_margin;
  double proj_margin_level = (proj_used_margin>0.0) ? (equity / proj_used_margin * 100.0) : 1000000.0;
  if(InpMinMarginLevelPct>0.0 && proj_margin_level < InpMinMarginLevelPct)
    return false;

  // Finalize out params
  out_volume = vol;
  out_est_margin = est_margin;
  return true;
}

void ApplyTrailingAndBreakeven()
{
  if(!InpAllowTrailing) return;
  if(PositionsTotal()==0) return;

  double ask, bid; SymbolInfoDouble(gSymbol, SYMBOL_ASK, ask); SymbolInfoDouble(gSymbol, SYMBOL_BID, bid);
  double atr=0.0; if(!GetLatestValues(hATR, atr, 0)) return;
  if(atr<=0.0) return;

  for(int i=0;i<PositionsTotal();i++)
  {
    ulong ticket = PositionGetTicket(i);
    if(ticket==0) continue;
    if(!PositionSelectByTicket(ticket)) continue;
    if(PositionGetString(POSITION_SYMBOL)!=gSymbol) continue;
    if(PositionGetInteger(POSITION_MAGIC)!=(long)InpMagicNumber) continue;

    long   type = PositionGetInteger(POSITION_TYPE);
    double sl   = PositionGetDouble(POSITION_SL);
    double price_open = PositionGetDouble(POSITION_PRICE_OPEN);
    double volume = PositionGetDouble(POSITION_VOLUME);

    // Determine trail distance
    double trail_dist = InpATR_TrailMult * atr;

    // Breakeven
    if(InpBreakevenRR>0.0)
    {
      double initial_sl_dist = MathAbs(price_open - sl);
      if(initial_sl_dist>0.0)
      {
        double be_trigger = initial_sl_dist * InpBreakevenRR;
        if(type==POSITION_TYPE_BUY)
        {
          if((bid - price_open) >= be_trigger)
          {
            double new_sl = MathMax(sl, price_open);
            new_sl = NormalizeDouble(new_sl, gDigits);
            if(new_sl>0 && new_sl!=sl)
            {
              if(!trade.PositionModify(ticket, new_sl, PositionGetDouble(POSITION_TP)))
                LogLastError("PositionModify BE (BUY) failed");
            }
          }
        }
        else if(type==POSITION_TYPE_SELL)
        {
          if((price_open - ask) >= be_trigger)
          {
            double new_sl = MathMin(sl, price_open);
            new_sl = NormalizeDouble(new_sl, gDigits);
            if(new_sl>0 && new_sl!=sl)
            {
              if(!trade.PositionModify(ticket, new_sl, PositionGetDouble(POSITION_TP)))
                LogLastError("PositionModify BE (SELL) failed");
            }
          }
        }
      }
    }

    // Trailing stop
    if(type==POSITION_TYPE_BUY)
    {
      double desired_sl = NormalizeDouble(bid - trail_dist, gDigits);
      if(sl<=0.0 || desired_sl > sl)
      {
        // Respect stop levels
        int min_dist_pts = MathMax(gStopsLevelPoints, gFreezeLevelPoints);
        double min_dist = min_dist_pts * gPoint;
        if((bid - desired_sl) >= min_dist)
        {
          if(!trade.PositionModify(ticket, desired_sl, PositionGetDouble(POSITION_TP)))
            LogLastError("PositionModify Trail (BUY) failed");
        }
      }
    }
    else if(type==POSITION_TYPE_SELL)
    {
      double desired_sl = NormalizeDouble(ask + trail_dist, gDigits);
      if(sl<=0.0 || desired_sl < sl)
      {
        int min_dist_pts = MathMax(gStopsLevelPoints, gFreezeLevelPoints);
        double min_dist = min_dist_pts * gPoint;
        if((desired_sl - ask) >= min_dist)
        {
          if(!trade.PositionModify(ticket, desired_sl, PositionGetDouble(POSITION_TP)))
            LogLastError("PositionModify Trail (SELL) failed");
        }
      }
    }
  }
}

bool GetEMARSISignals(bool &buy_signal, bool &sell_signal)
{
  buy_signal=false; sell_signal=false;

  // Use previous closed bar for signals to avoid intra-bar noise
  int shift = 1;

  double fast_curr, fast_prev, slow_curr, slow_prev, rsi_curr;
  if(CopyBuffer(hFastEMA,0,shift,2,&fast_prev)<=0) return false; // reuse buffer directly
  if(CopyBuffer(hSlowEMA,0,shift,2,&slow_prev)<=0) return false;
  if(!GetLatestValues(hRSI, rsi_curr, shift)) return false;

  // Extract values
  double fast_1 = fast_prev[0];
  double fast_2 = fast_prev[1];
  double slow_1 = slow_prev[0];
  double slow_2 = slow_prev[1];

  // Cross conditions
  bool bull_cross = (fast_2 <= slow_2) && (fast_1 > slow_1);
  bool bear_cross = (fast_2 >= slow_2) && (fast_1 < slow_1);

  if(bull_cross && rsi_curr >= InpRSI_Buy)
    buy_signal = true;
  if(bear_cross && rsi_curr <= InpRSI_Sell)
    sell_signal = true;

  return true;
}

bool BuildSLTP(const bool is_buy, const double atr, const double entry, double &sl, double &tp)
{
  if(atr<=0.0 || entry<=0.0) return false;
  double sl_dist = InpATR_SL_Mult * atr;
  double tp_dist = InpRR * sl_dist;

  if(is_buy)
  {
    sl = NormalizeDouble(entry - sl_dist, gDigits);
    tp = NormalizeDouble(entry + tp_dist, gDigits);
  }
  else
  {
    sl = NormalizeDouble(entry + sl_dist, gDigits);
    tp = NormalizeDouble(entry - tp_dist, gDigits);
  }

  // Respect stop levels
  int min_dist_pts = MathMax(gStopsLevelPoints, gFreezeLevelPoints);
  double min_dist = min_dist_pts * gPoint;
  if(is_buy)
  {
    if((entry - sl) < min_dist) sl = NormalizeDouble(entry - min_dist, gDigits);
    if((tp - entry) < min_dist) tp = NormalizeDouble(entry + min_dist, gDigits);
  }
  else
  {
    if((sl - entry) < min_dist) sl = NormalizeDouble(entry + min_dist, gDigits);
    if((entry - tp) < min_dist) tp = NormalizeDouble(entry - min_dist, gDigits);
  }

  return true;
}

//==================================================================
// OnInit / OnDeinit / OnTick
//==================================================================
int OnInit()
{
  if(!RefreshSymbolInfo(_Symbol))
  {
    Print("Failed to load symbol info");
    return INIT_FAILED;
  }

  ParseSkipHours(InpSkipHoursUTC);

  hFastEMA = iMA(gSymbol, InpTimeframe, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
  hSlowEMA = iMA(gSymbol, InpTimeframe, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
  hRSI     = iRSI(gSymbol, InpTimeframe, InpRSIPeriod, PRICE_CLOSE);
  hATR     = iATR(gSymbol, InpTimeframe, InpATRPeriod);

  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
  {
    Print("Indicator handle creation failed");
    return INIT_FAILED;
  }

  return INIT_SUCCEEDED;
}

void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);
}

void OnTick()
{
  if(IsStopped()) return;
  if(!RefreshSymbolInfo(_Symbol)) return;

  // One position per symbol (with this magic)
  if(CountOpenPositionsForSymbol(gSymbol, InpMagicNumber) > 0)
  {
    ApplyTrailingAndBreakeven();
    return;
  }

  // Session / spread filters
  if(IsSessionBlocked()) return;
  if(!CheckSpreadOk(gSymbol, InpMaxSpreadPoints)) return;

  // Get prices
  double ask=0.0, bid=0.0;
  if(!SymbolInfoDouble(gSymbol, SYMBOL_ASK, ask) || !SymbolInfoDouble(gSymbol, SYMBOL_BID, bid))
  {
    LogLastError("Failed to get quotes");
    return;
  }

  // Ensure indicator data is ready
  if(BarsCalculated(hFastEMA)<100 || BarsCalculated(hSlowEMA)<100 || BarsCalculated(hRSI)<100 || BarsCalculated(hATR)<100)
    return;

  // ATR filter
  double atr=0.0; if(!GetLatestValues(hATR, atr, 1)) return; // use closed bar ATR
  if(InpATR_MinFilter>0.0 && atr < InpATR_MinFilter) return;

  // Signals
  bool buy_signal=false, sell_signal=false;
  if(!GetEMARSISignals(buy_signal, sell_signal)) return;

  // Build order params
  bool is_buy=false; double entry=0.0;
  if(buy_signal) { is_buy=true; entry=ask; }
  else if(sell_signal) { is_buy=false; entry=bid; }
  else { return; }

  double sl=0.0, tp=0.0;
  if(!BuildSLTP(is_buy, atr, entry, sl, tp)) return;

  // Risk-based volume sizing with margin constraints
  double volume=0.0, est_margin=0.0;
  if(!CalcVolumeByRisk(is_buy, entry, sl, InpRiskPerTradePct, InpMaxFreeMarginUsagePct, volume, est_margin))
  {
    Print("CalcVolumeByRisk failed or constraints prevent opening");
    return;
  }

  // Final margin check with chosen volume
  double calc_margin=0.0;
  ENUM_ORDER_TYPE ot = is_buy ? ORDER_TYPE_BUY : ORDER_TYPE_SELL;
  if(!OrderCalcMargin(ot, gSymbol, volume, entry, calc_margin))
  {
    LogLastError("OrderCalcMargin final failed");
    return;
  }

  double free_margin=AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(calc_margin > free_margin)
  {
    Print("Not enough free margin for trade");
    return;
  }

  // Margin level projection re-check
  double equity=AccountInfoDouble(ACCOUNT_EQUITY);
  double used_margin=AccountInfoDouble(ACCOUNT_MARGIN);
  double proj_used = used_margin + calc_margin;
  double proj_ml = proj_used>0.0 ? (equity / proj_used * 100.0) : 1000000.0;
  if(InpMinMarginLevelPct>0.0 && proj_ml < InpMinMarginLevelPct)
  {
    PrintFormat("Projected margin level %.2f%% below minimum %.2f%%", proj_ml, InpMinMarginLevelPct);
    return;
  }

  // Prepare and send order
  trade.SetExpertMagicNumber((long)InpMagicNumber);
  trade.SetDeviationInPoints(InpSlippagePoints);

  bool sent=false;
  if(is_buy)
  {
    sent = trade.Buy(volume, gSymbol, entry, sl, tp, "EMA/RSI BUY");
  }
  else
  {
    sent = trade.Sell(volume, gSymbol, entry, sl, tp, "EMA/RSI SELL");
  }

  if(!sent)
  {
    LogLastError("Order send failed");
    return;
  }

  // Post-open trailing/breakeven management will occur on subsequent ticks
}

