//|  EMA Cross + RSI + ATR with robust risk & margin controls        |
//|  One-position-per-symbol, spread/session filters, trailing stop  |
//+------------------------------------------------------------------+
#property copyright ""
#property link      ""
#property version   "1.00"
#property strict

#include <Trade/Trade.mqh>

//--- Inputs
input int      FastEMAPeriod          = 12;
input int      SlowEMAPeriod          = 26;
input ENUM_APPLIED_PRICE EMAPrice     = PRICE_CLOSE;
input int      RSIPeriod              = 14;
input int      RSIOverbought          = 70;
input int      RSIOversold            = 30;
input int      ATRPeriod              = 14;
input double   ATRStopMultiplier      = 2.0;     // SL = ATR * multiplier
input double   ATRTrailMultiplier     = 1.5;     // trailing distance in ATR
input double   TP_RR_Multiple         = 2.0;     // TP = SL * multiple

input double   MaxSpreadPoints        = 25;      // max allowed spread in points
input double   RiskPerTradePct        = 1.0;     // percent of equity at risk
input double   PerTradeMarginCapPct   = 20.0;    // cap margin per trade as % of free margin
input double   MinMarginLevelPct      = 150.0;   // do not trade if margin level below

input bool     UseSessionFilter       = true;
input int      SessionStartHour       = 7;       // broker time
input int      SessionEndHour         = 20;      // broker time

input bool     AllowLongs             = true;
input bool     AllowShorts            = true;
input bool     EnableTrailing         = true;
input bool     OnePositionPerSymbol   = true;

//--- Globals
CTrade         trade;
int            hFastEMA = INVALID_HANDLE;
int            hSlowEMA = INVALID_HANDLE;
int            hRSI     = INVALID_HANDLE;
int            hATR     = INVALID_HANDLE;
MqlTick        lastTick;

//--- Helper: log and error text
string ErrorText(int code){
   string err=ErrorDescription(code);
   if(err=="") err = IntegerToString(code);
   return err;
}

bool GetLatestTick(){
   if(!SymbolInfoTick(_Symbol,lastTick)){
      PrintFormat("[ERROR] SymbolInfoTick failed (%s)", ErrorText(GetLastError()));
      return false;
   }
   return true;
}

bool InSession(){
   if(!UseSessionFilter) return true;
   datetime now = TimeCurrent();
   int h = TimeHour(now);
   if(SessionStartHour<=SessionEndHour)
      return (h>=SessionStartHour && h<SessionEndHour);
   // overnight window
   return (h>=SessionStartHour || h<SessionEndHour);
}

bool SpreadOK(){
   if(!GetLatestTick()) return false;
   double pt = SymbolInfoDouble(_Symbol,SYMBOL_POINT);
   if(pt<=0){ Print("[ERROR] Invalid point size"); return false; }
   double spreadPoints = (lastTick.ask - lastTick.bid)/pt;
   if(spreadPoints>MaxSpreadPoints){
      PrintFormat("[INFO] Spread too high: %.1f > %.1f points", spreadPoints, MaxSpreadPoints);
      return false;
   }
   return true;
}

bool HasOpenPositionForSymbol(){
   if(!OnePositionPerSymbol) return false;
   for(int i=0;i<PositionsTotal();++i){
      ulong ticket = PositionGetTicket(i);
      if(ticket==0) continue;
      if(!PositionSelectByTicket(ticket)) continue;
      if(PositionGetString(POSITION_SYMBOL)==_Symbol) return true;
   }
   return false;
}

//--- Indicator values
bool GetIndicators(double &fast, double &slow, double &rsi, double &atr){
   fast = slow = rsi = atr = 0.0;
   double bufFast[], bufSlow[], bufRSI[], bufATR[];
   if(CopyBuffer(hFastEMA,0,0,2,bufFast)<2){ Print("[ERROR] CopyBuffer fast EMA"); return false; }
   if(CopyBuffer(hSlowEMA,0,0,2,bufSlow)<2){ Print("[ERROR] CopyBuffer slow EMA"); return false; }
   if(CopyBuffer(hRSI,0,0,1,bufRSI)<1){ Print("[ERROR] CopyBuffer RSI"); return false; }
   if(CopyBuffer(hATR,0,0,1,bufATR)<1){ Print("[ERROR] CopyBuffer ATR"); return false; }
   fast = bufFast[0];
   slow = bufSlow[0];
   rsi  = bufRSI[0];
   atr  = bufATR[0];
   if(!MathIsValidNumber(fast) || !MathIsValidNumber(slow) || !MathIsValidNumber(rsi) || !MathIsValidNumber(atr)){
      Print("[ERROR] Invalid indicator values");
      return false;
   }
   return true;
}

//--- Directional signals
bool LongSignal(){
   double f,s,r,a; if(!GetIndicators(f,s,r,a)) return false;
   if(f>s && r<RSIOverbought) return true;
   return false;
}

bool ShortSignal(){
   double f,s,r,a; if(!GetIndicators(f,s,r,a)) return false;
   if(f<s && r>RSIOversold) return true;
   return false;
}

//--- Position sizing via OrderCalcMargin with risk, free margin and margin level checks
bool ComputeOrder(double stopDistancePts, ENUM_ORDER_TYPE orderType, double &volume, double &slPrice, double &tpPrice){
   volume = 0.0; slPrice = 0.0; tpPrice = 0.0;
   if(!GetLatestTick()) return false;

   double pt     = SymbolInfoDouble(_Symbol,SYMBOL_POINT);
   double tickSz = SymbolInfoDouble(_Symbol,SYMBOL_TRADE_TICK_SIZE);
   double tickVal= SymbolInfoDouble(_Symbol,SYMBOL_TRADE_TICK_VALUE);
   double minLot = SymbolInfoDouble(_Symbol,SYMBOL_VOLUME_MIN);
   double maxLot = SymbolInfoDouble(_Symbol,SYMBOL_VOLUME_MAX);
   double lotStep= SymbolInfoDouble(_Symbol,SYMBOL_VOLUME_STEP);
   double contractSize = SymbolInfoDouble(_Symbol,SYMBOL_TRADE_CONTRACT_SIZE);
   if(pt<=0 || tickSz<=0 || tickVal<=0 || minLot<=0 || maxLot<=0 || lotStep<=0){
      Print("[ERROR] Invalid symbol trading properties");
      return false;
   }

   double equity      = AccountInfoDouble(ACCOUNT_EQUITY);
   double freeMargin  = AccountInfoDouble(ACCOUNT_FREEMARGIN);
   double marginLevel = AccountInfoDouble(ACCOUNT_MARGIN_LEVEL);
   if(!MathIsValidNumber(equity) || !MathIsValidNumber(freeMargin) || !MathIsValidNumber(marginLevel)){
      Print("[ERROR] Invalid account metrics");
      return false;
   }
   if(marginLevel>0 && marginLevel < MinMarginLevelPct){
      PrintFormat("[INFO] Margin level %.1f%% below threshold %.1f%%", marginLevel, MinMarginLevelPct);
      return false;
   }

   // Determine SL distance in price from ATR multiplier
   double atr; { double f,s,r,a; if(!GetIndicators(f,s,r,a)) return false; atr=a; }
   if(atr<=0){ Print("[ERROR] ATR <= 0"); return false; }

   double slDistPts = stopDistancePts; // already in points from caller
   if(slDistPts<=0){ Print("[ERROR] stopDistancePts <= 0"); return false; }
   double slDistPrice = slDistPts * pt;

   // Risk-based position size estimation in lots: risk = equity * RiskPerTradePct%
   double riskMoney = equity * (RiskPerTradePct/100.0);
   if(riskMoney<=0){ Print("[ERROR] Computed riskMoney <= 0"); return false; }

   // Value per point per 1 lot in deposit currency
   // Approximate via tick value: value_per_point = tickVal * (pt / tickSz)
   double valuePerPointPerLot = tickVal * (pt / tickSz);
   if(valuePerPointPerLot<=0){ Print("[ERROR] valuePerPointPerLot <= 0"); return false; }

   double rawLotsByRisk = riskMoney / (slDistPts * valuePerPointPerLot);
   if(rawLotsByRisk<=0){ Print("[INFO] rawLotsByRisk <= 0"); return false; }

   // Snap to broker lot step within min/max
   double lots = MathFloor(rawLotsByRisk/lotStep)*lotStep;
   lots = MathMax(minLot, MathMin(lots, maxLot));
   if(lots<minLot){ Print("[INFO] Computed lots below minLot"); return false; }

   // Margin estimation using OrderCalcMargin, apply per-trade margin cap
   double price = (orderType==ORDER_TYPE_BUY || orderType==ORDER_TYPE_BUY_LIMIT || orderType==ORDER_TYPE_BUY_STOP) ? lastTick.ask : lastTick.bid;
   double estMargin=0.0;
   if(!OrderCalcMargin(orderType,_Symbol,lots,price,estMargin)){
      PrintFormat("[ERROR] OrderCalcMargin failed: %s", ErrorText(GetLastError()));
      return false;
   }
   if(estMargin<=0){ Print("[ERROR] Estimated margin <= 0"); return false; }

   double marginCap = freeMargin * (PerTradeMarginCapPct/100.0);
   if(marginCap<=0){ Print("[INFO] marginCap <= 0"); return false; }

   // Reduce lots if margin exceeds cap or free margin
   if(estMargin>marginCap || estMargin>freeMargin){
      double cap = MathMin(marginCap, freeMargin);
      if(cap<=0){ Print("[INFO] Cap/free margin <= 0"); return false; }
      double scale = cap/estMargin;
      if(scale<=0){ Print("[INFO] scale <= 0"); return false; }
      double adjLots = MathFloor((lots*scale)/lotStep)*lotStep;
      adjLots = MathMax(0.0, MathMin(adjLots, lots));
      if(adjLots<minLot){
         PrintFormat("[INFO] Adjusted lots %.2f below minLot %.2f due to margin cap", adjLots, minLot);
         return false;
      }
      lots = adjLots;
      if(!OrderCalcMargin(orderType,_Symbol,lots,price,estMargin)){
         PrintFormat("[ERROR] OrderCalcMargin recheck failed: %s", ErrorText(GetLastError()));
         return false;
      }
      if(estMargin>cap){
         Print("[INFO] Estimated margin still above cap after adjustment");
         return false;
      }
   }

   // Final SL/TP prices
   if(orderType==ORDER_TYPE_BUY){
      slPrice = price - slDistPrice;
      double tpDist = slDistPrice * TP_RR_Multiple;
      tpPrice = price + tpDist;
   } else if(orderType==ORDER_TYPE_SELL){
      slPrice = price + slDistPrice;
      double tpDist = slDistPrice * TP_RR_Multiple;
      tpPrice = price - tpDist;
   } else {
      Print("[ERROR] Unsupported order type for market computation");
      return false;
   }

   // Normalize prices and volume
   int digits = (int)SymbolInfoInteger(_Symbol,SYMBOL_DIGITS);
   slPrice = NormalizeDouble(slPrice,digits);
   tpPrice = NormalizeDouble(tpPrice,digits);
   lots    = NormalizeDouble(lots, (int)MathRound(-MathLog10(lotStep)) );

   // Validate stops distance against symbol limits
   double stopLevelPts = SymbolInfoInteger(_Symbol,SYMBOL_TRADE_STOPS_LEVEL);
   double freezeLevelPts = SymbolInfoInteger(_Symbol,SYMBOL_TRADE_FREEZE_LEVEL);
   double minStopPts = (double)MathMax(stopLevelPts, freezeLevelPts);

   if(orderType==ORDER_TYPE_BUY){
      if((price - slPrice)/pt < minStopPts){
         double target = price - (minStopPts*pt);
         slPrice = NormalizeDouble(target,digits);
      }
      if((tpPrice - price)/pt < minStopPts){
         double target = price + (minStopPts*pt);
         tpPrice = NormalizeDouble(target,digits);
      }
   } else if(orderType==ORDER_TYPE_SELL){
      if((slPrice - price)/pt < minStopPts){
         double target = price + (minStopPts*pt);
         slPrice = NormalizeDouble(target,digits);
      }
      if((price - tpPrice)/pt < minStopPts){
         double target = price - (minStopPts*pt);
         tpPrice = NormalizeDouble(target,digits);
      }
   }

   volume = lots;
   return true;
}

void TrailPosition(){
   if(!EnableTrailing) return;
   if(!GetLatestTick()) return;
   double pt = SymbolInfoDouble(_Symbol,SYMBOL_POINT);
   int digits = (int)SymbolInfoInteger(_Symbol,SYMBOL_DIGITS);

   if(!PositionSelect(_Symbol)) return;
   long   type   = PositionGetInteger(POSITION_TYPE);
   double price  = (type==POSITION_TYPE_BUY) ? lastTick.bid : lastTick.ask;
   double sl     = PositionGetDouble(POSITION_SL);

   double atr; { double f,s,r,a; if(!GetIndicators(f,s,r,a)) return; atr=a; }
   if(atr<=0) return;
   double trailDist = ATRTrailMultiplier * atr; // in price units

   if(type==POSITION_TYPE_BUY){
      double newSL = price - trailDist;
      if(sl==0 || newSL>sl){
         newSL = NormalizeDouble(newSL,digits);
         if(!trade.PositionModify(_Symbol,newSL,PositionGetDouble(POSITION_TP))){
            PrintFormat("[WARN] Trail modify failed (BUY): %s", ErrorText(trade.ResultRetcode()));
         }
      }
   } else if(type==POSITION_TYPE_SELL){
      double newSL = price + trailDist;
      if(sl==0 || newSL<sl){
         newSL = NormalizeDouble(newSL,digits);
         if(!trade.PositionModify(_Symbol,newSL,PositionGetDouble(POSITION_TP))){
            PrintFormat("[WARN] Trail modify failed (SELL): %s", ErrorText(trade.ResultRetcode()));
         }
      }
   }
}

//--- OnInit
int OnInit(){
   // Create indicators
   hFastEMA = iMA(_Symbol, PERIOD_CURRENT, FastEMAPeriod, 0, MODE_EMA, EMAPrice);
   if(hFastEMA==INVALID_HANDLE){ Print("[ERROR] iMA fast handle"); return(INIT_FAILED); }

   hSlowEMA = iMA(_Symbol, PERIOD_CURRENT, SlowEMAPeriod, 0, MODE_EMA, EMAPrice);
   if(hSlowEMA==INVALID_HANDLE){ Print("[ERROR] iMA slow handle"); return(INIT_FAILED); }

   hRSI = iRSI(_Symbol, PERIOD_CURRENT, RSIPeriod, PRICE_CLOSE);
   if(hRSI==INVALID_HANDLE){ Print("[ERROR] iRSI handle"); return(INIT_FAILED); }

   hATR = iATR(_Symbol, PERIOD_CURRENT, ATRPeriod);
   if(hATR==INVALID_HANDLE){ Print("[ERROR] iATR handle"); return(INIT_FAILED); }

   if(!GetLatestTick()){
      Print("[ERROR] Initial tick unavailable");
      return(INIT_FAILED);
   }

   trade.SetAsyncMode(false);
   Print("[INIT] EMA_RSI_ATR_Manager initialized");
   return(INIT_SUCCEEDED);
}

//--- OnTick
void OnTick(){
   if(!InSession()) return;
   if(!SpreadOK()) return;

   // Ensure only one position if configured
   if(OnePositionPerSymbol && HasOpenPositionForSymbol()){
      TrailPosition();
      return;
   }

   // Market entry logic
   double f,s,r,atr; if(!GetIndicators(f,s,r,atr)) return;
   if(atr<=0) return;

   double pt = SymbolInfoDouble(_Symbol,SYMBOL_POINT);
   if(pt<=0) return;

   // Set SL based on ATR multiplier in points
   double slDistPts = (ATRStopMultiplier * atr)/pt;

   // Buy
   if(AllowLongs && LongSignal()){
      double vol,sl,tp; if(!ComputeOrder(slDistPts, ORDER_TYPE_BUY, vol, sl, tp)) return;
      trade.SetDeviationInPoints(10);
      if(!trade.Buy(vol,NULL,0.0,sl,tp)){
         PrintFormat("[ERROR] Buy failed: %s", ErrorText(trade.ResultRetcode()));
      }
      return;
   }

   // Sell
   if(AllowShorts && ShortSignal()){
      double vol,sl,tp; if(!ComputeOrder(slDistPts, ORDER_TYPE_SELL, vol, sl, tp)) return;
      trade.SetDeviationInPoints(10);
      if(!trade.Sell(vol,NULL,0.0,sl,tp)){
         PrintFormat("[ERROR] Sell failed: %s", ErrorText(trade.ResultRetcode()));
      }
      return;
   }
}

//--- OnDeinit
void OnDeinit(const int reason){
   if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
   if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
   if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
   if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);
   Print("[DEINIT] Reason: ", reason);
}
